package com.tcgrace;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class OsrsTcgIntegrationService
{
	private static final String GROUP = "osrstcg";

	private final ConfigManager configManager;

	@Inject
	OsrsTcgIntegrationService(ConfigManager configManager)
	{
		this.configManager = configManager;
	}

	boolean isImmediateDetectionReady()
	{
		return valueIs("partyAnnouncePulls", "true")
			&& valueIs("pullNotificationTrigger", "EVERY_CARD")
			&& valueIs("notifyTier", "COMMON")
			&& valueIs("duplicateNotifyTier", "COMMON")
			&& valueIs("notifyNewCardsOnly", "false")
			&& valueIs("notifyNonFoils", "true")
			&& valueIs("notifyFoils", "true");
	}

	boolean enableImmediateDetection()
	{
		set("partyAnnouncePulls", true);
		set("pullNotificationTrigger", "EVERY_CARD");
		set("notifyTier", "COMMON");
		set("duplicateNotifyTier", "COMMON");
		set("notifyNewCardsOnly", false);
		set("notifyNonFoils", true);
		set("notifyFoils", true);
		return isImmediateDetectionReady();
	}

	private boolean valueIs(String key, String expected)
	{
		String value = configManager.getConfiguration(GROUP, key);
		return value != null && expected.equalsIgnoreCase(value.trim());
	}

	private void set(String key, Object value)
	{
		configManager.setConfiguration(GROUP, key, value);
	}
}

package com.tcgrace;

import com.tcgrace.model.MatchState;
import com.tcgrace.model.RaceCard;
import com.tcgrace.model.RacePlacement;
import com.tcgrace.model.RaceSnapshot;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

@Singleton
public class RaceOverlay extends OverlayPanel
{
	private static final Color MUTED = new Color(180, 180, 180);
	private static final Color DANGER = new Color(255, 104, 104);
	/** Rows are rebuilt every frame, so a large party is summarised rather than listed in full. */
	private static final int MAX_RACER_ROWS = 12;
	private static final int MAX_SCORE_ROWS = 10;

	private final RaceService raceService;
	private final TcgRaceConfig config;

	@Inject
	RaceOverlay(RaceService raceService, TcgRaceConfig config)
	{
		this.raceService = raceService;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setPriority(PRIORITY_HIGH);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		panelComponent.setPreferredSize(new Dimension(365, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}
		RaceSnapshot snapshot = raceService.snapshot();
		if (snapshot.getState() == RaceSnapshot.State.IDLE)
		{
			return null;
		}

		long now = System.currentTimeMillis();
		panelComponent.getChildren().clear();
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(title(snapshot, now))
			.color(config.activeColor())
			.build());

		if (snapshot.isLocalInvalid())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("INVALID: " + snapshot.getLocalInvalidReason())
				.leftColor(DANGER)
				.build());
		}

		if (!snapshot.getParticipants().isEmpty())
		{
			// One pass to index the round result, so a big field stays linear per frame.
			Map<String, RacePlacement> byName = new HashMap<>();
			for (RacePlacement placement : snapshot.getPlacements())
			{
				byName.put(placement.getPlayerName().toLowerCase(Locale.ROOT), placement);
			}
			Set<String> dnf = new HashSet<>();
			for (String playerName : snapshot.getDnfPlayers())
			{
				dnf.add(playerName.toLowerCase(Locale.ROOT));
			}

			List<String> racers = snapshot.getParticipants();
			panelComponent.getChildren().add(TitleComponent.builder()
				.text("RACERS (" + racers.size() + ")")
				.color(Color.WHITE)
				.build());
			int shown = Math.min(racers.size(), MAX_RACER_ROWS);
			for (int index = 0; index < shown; index++)
			{
				String participant = racers.get(index);
				String key = participant.toLowerCase(Locale.ROOT);
				RacePlacement placement = byName.get(key);
				panelComponent.getChildren().add(LineComponent.builder()
					.left("• " + participant)
					.right(racerStatus(snapshot, placement, dnf.contains(key)))
					.leftColor(MUTED)
					.rightColor(racerStatusColor(placement, dnf.contains(key)))
					.build());
			}
			if (racers.size() > shown)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("  and " + (racers.size() - shown) + " more")
					.leftColor(MUTED)
					.build());
			}
		}

		for (RaceCard card : snapshot.getCards())
		{
			List<RacePlacement> cardPlacements = placementsForCard(snapshot.getPlacements(), card.getIndex());
			String objective = (card.getIndex() + 1) + ". " + card.getKind().getAction() + " " + card.getDisplayName();
			Color color = cardPlacements.isEmpty() ? config.activeColor() : config.finishedColor();
			panelComponent.getChildren().add(LineComponent.builder()
				.left(objective)
				.leftColor(color)
				.build());
			for (RacePlacement placement : cardPlacements)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("   " + RaceService.ordinal(placement.getPlace()) + "  " + placement.getPlayerName()
						+ "  (+" + placement.getPoints() + ")")
					.right(RaceService.formatDuration(placement.getElapsedMillis()))
					.leftColor(config.finishedColor())
					.rightColor(Color.WHITE)
					.build());
			}
		}

		if (config.showScoreboard() && !snapshot.getScores().isEmpty())
		{
			panelComponent.getChildren().add(TitleComponent.builder().text("MATCH SCORE").color(Color.WHITE).build());
			List<Map.Entry<String, Integer>> scores = new ArrayList<>(snapshot.getScores().entrySet());
			scores.sort(Map.Entry.<String, Integer>comparingByValue(Comparator.reverseOrder())
				.thenComparing(Map.Entry.comparingByKey(String.CASE_INSENSITIVE_ORDER)));
			int shown = Math.min(scores.size(), MAX_SCORE_ROWS);
			for (int index = 0; index < shown; index++)
			{
				Map.Entry<String, Integer> score = scores.get(index);
				panelComponent.getChildren().add(LineComponent.builder()
					.left(score.getKey())
					.right(score.getValue() + " pts")
					.leftColor(MUTED)
					.rightColor(Color.WHITE)
					.build());
			}
			if (scores.size() > shown)
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left("  and " + (scores.size() - shown) + " more")
					.leftColor(MUTED)
					.build());
			}
		}
		return super.render(graphics);
	}

	private String title(RaceSnapshot snapshot, long now)
	{
		String prefix = "TCGG";
		MatchState match = snapshot.getMatch();
		if (match.getRound() > 0)
		{
			prefix += match.getTotalRounds() > 0
				? " R" + match.getRound() + "/" + match.getTotalRounds()
				: " R" + match.getRound();
		}
		switch (snapshot.getState())
		{
			case COUNTDOWN:
				return config.showObjectiveTimers()
					? prefix + " • STARTS IN " + Math.max(0L, (snapshot.getStartsAt() - now + 999L) / 1_000L)
					: prefix;
			case RUNNING:
				if (!config.showObjectiveTimers())
				{
					return prefix;
				}
				return snapshot.getDnfDeadlineAt() > 0L
					? prefix + " • DNF IN " + RaceService.formatDuration(snapshot.getDnfDeadlineAt() - now)
					: prefix + " • " + RaceService.formatDuration(now - snapshot.getStartsAt());
			case FINISHED:
				return match.isComplete()
					? prefix + " • MATCH COMPLETE" : prefix + " • ROUND COMPLETE";
			default:
				return prefix;
		}
	}

	private String racerStatus(RaceSnapshot snapshot, RacePlacement placement, boolean dnf)
	{
		if (placement != null)
		{
			return RaceService.ordinal(placement.getPlace()) + "  +" + placement.getPoints();
		}
		if (dnf)
		{
			return "DNF";
		}
		return snapshot.getState() == RaceSnapshot.State.RUNNING ? "racing" : "ready";
	}

	private static Color racerStatusColor(RacePlacement placement, boolean dnf)
	{
		if (placement != null)
		{
			return Color.WHITE;
		}
		return dnf ? DANGER : MUTED;
	}

	private static List<RacePlacement> placementsForCard(List<RacePlacement> placements, int cardIndex)
	{
		List<RacePlacement> result = new ArrayList<>();
		for (RacePlacement placement : placements)
		{
			if (placement.getCardIndex() == cardIndex)
			{
				result.add(placement);
			}
		}
		return result;
	}
}

package com.tcgrace;

import com.google.gson.Gson;
import com.tcgrace.model.MatchState;
import com.tcgrace.model.ObjectiveKind;
import com.tcgrace.model.RaceCard;
import com.tcgrace.model.RacePlacement;
import com.tcgrace.model.RaceSnapshot;
import com.tcgrace.party.RaceClaimMessage;
import com.tcgrace.party.RaceCountdownHoldMessage;
import com.tcgrace.party.RacePlacementMessage;
import com.tcgrace.party.RaceReadyMessage;
import com.tcgrace.party.RaceRoundCancelMessage;
import com.tcgrace.party.RaceRoundEndMessage;
import com.tcgrace.party.RaceRoundStartMessage;
import com.tcgrace.party.RaceScoreResetMessage;
import com.tcgrace.party.RaceStateRequestMessage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuEntry;
import net.runelite.api.MenuAction;
import net.runelite.api.NPC;
import net.runelite.api.Player;
