import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.util.Text;

@Slf4j
@Singleton
public class RaceService
{
	private static final String SCORE_KEY = "scoreboard";
	/** Prefix on every in-game message this plugin writes. */
	static final String CHAT_PREFIX = "[TCGG] ";
	private static final int NPC_ENGAGEMENT_TICKS = 12;
	private static final long STATE_BROADCAST_INTERVAL_MILLIS = 5_000L;
	private static final WorldPoint KANDARIN_MONASTERY = new WorldPoint(2606, 3219, 0);

	private final Client client;
	private final TcgRaceConfig config;
	private final PartyService partyService;
	private final TcgCatalogService catalogService;
	private final ItemManager itemManager;
	private final ConfigManager configManager;
	private final Gson gson;

	private final Map<String, Integer> scores = new LinkedHashMap<>();
	private final List<RacePlacement> placements = new ArrayList<>();
	private final Map<Integer, Integer> itemBaseline = new HashMap<>();
	private final Map<Integer, Integer> engagedNpcs = new HashMap<>();
	private List<RaceCard> cards = Collections.emptyList();
	private List<String> participants = Collections.emptyList();
	private final List<String> dnfPlayers = new ArrayList<>();
	/** Racers who have pressed Ready up for the next round. */
	private final List<String> readyPlayers = new ArrayList<>();
	/** Points this round handed out, so a cancelled round can hand them back. */
	private final Map<String, Integer> roundAwards = new LinkedHashMap<>();
	/** A pack opened before the party was ready, held until the last racer readies up. */
	private List<String> pendingPack = Collections.emptyList();
	private String roundId = "";
	private RaceSnapshot.State state = RaceSnapshot.State.IDLE;
	private long startsAt;
	private long endsAt;
	private long dnfDeadlineAt;
	private long finishedAt;
	private long hostMemberId;
	private WorldPoint countdownOrigin;
	private boolean localHost;
	private boolean baselineCaptured;
	private boolean localClaimSent;
	private boolean localInvalid;
	private boolean countdownLockNoticeShown;
	private boolean countdownHoldSent;
	private String localInvalidReason = "";
	private long lastStateBroadcastAt;
	private String unresolvedRoundId = "";
	private boolean spectatorNoticeShown;
	/** 1-based number of the current or most recent round in this match. */
	private int matchRound;
	/** Rounds the current match is scheduled to run, mirrored from the host. 0 means open ended. */
	private int matchTotalRounds;
	/** Rounds completed in this match. Cancelled rounds do not count. */
	private int roundsPlayed;
	/** Wall clock seam so simulated races can advance time without sleeping. */
	private LongSupplier clock = System::currentTimeMillis;

	@Inject
	RaceService(Client client, TcgRaceConfig config, PartyService partyService,
		TcgCatalogService catalogService, ItemManager itemManager, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.config = config;
		this.partyService = partyService;
		this.catalogService = catalogService;
		this.itemManager = itemManager;
		this.configManager = configManager;
		this.gson = gson;
	}

	synchronized void useClock(LongSupplier replacement)
	{
		clock = replacement == null ? System::currentTimeMillis : replacement;
	}

	private long now()
	{
		return clock.getAsLong();
	}

	synchronized void start()
	{
		loadScores();
	}

	synchronized void stop()
	{
		if (localHost && isActive())
		{
			endHostedRound("Host left the race");
		}
		clearRound();
	}

	synchronized void profileChanged()
	{
		clearRound();
		scores.clear();
		roundsPlayed = 0;
		loadScores();
	}

	synchronized void setLocalReady(boolean ready)
	{
		String playerName = localPlayerName();
		if (ready == isReady(playerName))
		{
			return;
		}
		markReady(playerName, ready);
		if (partyService.isInParty())
		{
			RaceReadyMessage message = new RaceReadyMessage();
			message.setPlayerName(playerName);
			message.setReady(ready);
			partyService.send(message);
		}
		gameMessage(ready ? "You are ready for the next round." : "You are no longer ready.");
		startArmedPackIfReady();
	}

	synchronized void onReady(RaceReadyMessage message)
	{
		if (message == null || isLocalSender(message.getMemberId()))
		{
			return;
		}
		String playerName = partyName(message.getMemberId());
		if ("A party member".equals(playerName))
		{
			playerName = cleanPlayerName(message.getPlayerName());
		}
		if (playerName.isEmpty())
		{
			return;
		}
		markReady(playerName, message.isReady());
		gameMessage(playerName + (message.isReady() ? " is ready." : " is no longer ready."));
		startArmedPackIfReady();
	}

	/** Runs a pack that was opened before the party was ready, now that everybody is. */
	private void startArmedPackIfReady()
	{
		if (pendingPack.isEmpty() || isActive() || !waitingOnReady().isEmpty())
		{
			return;
		}
		List<String> armed = pendingPack;
		pendingPack = Collections.emptyList();
		gameMessage("Everybody is ready. Starting the armed pack.");
		startRoundFromPack(armed);
	}

	private void markReady(String playerName, boolean ready)
	{
		String clean = cleanPlayerName(playerName);
		readyPlayers.removeIf(existing -> normalize(existing).equals(normalize(clean)));
		if (ready && !clean.isEmpty())
		{
			readyPlayers.add(clean);
		}
	}

	private boolean isReady(String playerName)
	{
		String wanted = normalize(playerName);
		for (String existing : readyPlayers)
		{
			if (normalize(existing).equals(wanted))
			{
				return true;
			}
		}
		return false;
	}

	/** Party members who still have to press Ready up before a round can begin. */
	private List<String> waitingOnReady()
	{
		List<String> waiting = new ArrayList<>();
		for (String participant : captureParticipants())
		{
			if (!isReady(participant))
			{
				waiting.add(participant);
			}
		}
		return waiting;
	}

	// --- Round lifecycle ---------------------------------------------------

	synchronized void onDetectedPack(List<String> pulledNames)
	{
		if (!config.autoStartFromPack())
		{
			log.debug("Ignored a detected OSRS TCG pack because this client does not host rounds");
			return;
		}
		startRoundFromPack(pulledNames);
	}

	private void startRoundFromPack(List<String> pulledNames)
	{
		if (isActive())
		{
			log.debug("Ignored detected OSRS TCG pack because a round is already active");
			return;
		}
		if (!partyService.isInParty() && !config.allowLocalWithoutParty())
		{
			log.debug("Rejected detected OSRS TCG pack because no RuneLite Party is active");
			gameMessage("Join a RuneLite Party before opening the race pack.");
			return;
		}
		int scheduledRounds = Math.max(0, config.totalRounds());
		if (scheduledRounds > 0 && roundsPlayed >= scheduledRounds)
		{
			log.debug("Refused a new round because the {}-round match is complete", scheduledRounds);
			gameMessage("This " + scheduledRounds + "-round match is complete. "
				+ matchResultLine() + " Press Reset scores to start a new match.");
			return;
		}
		if (config.requireEveryoneReady() && partyService.isInParty())
		{
			List<String> waiting = waitingOnReady();
			if (!waiting.isEmpty())
			{
				// Hold the pack rather than waste it. It starts by itself once the last racer readies.
				pendingPack = new ArrayList<>(pulledNames);
				log.debug("Armed a pack while {} racers are not ready", waiting.size());
				gameMessage("Pack armed. The round starts as soon as "
					+ String.join(", ", waiting) + " ready up.");
				return;
			}
		}
		pendingPack = Collections.emptyList();
		List<RaceCard> resolved = catalogService.resolvePack(pulledNames);
		if (resolved.size() != 5)
		{
			log.debug("Rejected detected OSRS TCG pack because it resolved to {} cards", resolved.size());
			gameMessage("A race pack must contain exactly five cards.");
			return;
		}
		for (RaceCard card : resolved)
		{
			if (card.getKind() == ObjectiveKind.UNKNOWN || card.getTargetIds().isEmpty())
			{
				log.debug("Rejected detected OSRS TCG pack because card '{}' has no supported objective", card.getCardName());
				gameMessage("Could not resolve the card '" + card.getCardName()
					+ "'. Open the OSRS TCG sidebar to refresh its live catalog, then open another pack.");
				return;
			}
		}
		long now = now();
		long start = now + Math.max(0, config.countdownSeconds()) * 1_000L;
		long end = start + Math.max(1, config.roundTimeoutMinutes()) * 60_000L;
		PartyMember localMember = partyService.getLocalMember();
		long memberId = localMember == null ? 0L : localMember.getMemberId();
		beginRound(UUID.randomUUID().toString(), start, end, resolved, captureParticipants(), memberId, true,
			roundsPlayed + 1, scheduledRounds);
		if (partyService.isInParty())
		{
			partyService.send(toStartMessage());
		}
		gameMessage("Five objectives synchronized. The race begins after the countdown.");
	}

	synchronized void onRoundStart(RaceRoundStartMessage message)
	{
		if (message == null || (localHost && isLocalSender(message.getMemberId())))
		{
			return;
		}
		if (message.getRoundId() == null || message.getRoundId().trim().isEmpty())
		{
			return;
		}
		if (message.getRoundId().equals(roundId) && isActive())
		{
			if (state == RaceSnapshot.State.COUNTDOWN && message.getStartsAt() > startsAt)
			{
				startsAt = message.getStartsAt();
				endsAt = message.getEndsAt();
				countdownOrigin = currentLocation();
				countdownHoldSent = false;
			}
			return;
		}
		List<RaceCard> incoming = cardsFrom(message);
		if (incoming.size() != 5)
		{
			// The live catalog has not resolved the host's cards yet, so keep asking until it can.
			if (!message.getRoundId().equals(unresolvedRoundId))
			{
				unresolvedRoundId = message.getRoundId();
				gameMessage("A race started, but this client cannot resolve its cards yet."
					+ " Open the OSRS TCG sidebar to refresh the live catalog.");
			}
			log.debug("Could not resolve the cards for synchronized round {}", message.getRoundId());
			return;
		}
		beginRound(message.getRoundId(), message.getStartsAt(), message.getEndsAt(), incoming,
			message.getParticipants(), message.getMemberId(), false,
			Math.max(1, message.getMatchRound()), Math.max(0, message.getTotalRounds()));
		log.debug("Accepted synchronized TCGG round {} from party member {}", message.getRoundId(), message.getMemberId());
		gameMessage("A TCGG round was started by " + partyName(message.getMemberId()) + ".");
		if (!config.showOverlay())
		{
			gameMessage("The race HUD is disabled on this account. Enable 'Show race overlay' in TCGG settings.");
		}
	}

	synchronized void onCountdownHold(RaceCountdownHoldMessage message)
	{
		if (!localHost || message == null || state != RaceSnapshot.State.COUNTDOWN
			|| !roundId.equals(message.getRoundId()) || isLocalSender(message.getMemberId()))
		{
			return;
		}
		restartCountdown();
	}

	synchronized void onClaim(RaceClaimMessage message)
	{
		if (!localHost || message == null || !roundId.equals(message.getRoundId())
			|| state != RaceSnapshot.State.RUNNING || message.getCardIndex() < 0 || message.getCardIndex() >= cards.size())
		{
			return;
		}
		String claimant = cleanPlayerName(message.getPlayerName());
		String partyClaimant = partyName(message.getMemberId());
		if (!"A party member".equals(partyClaimant))
		{
			claimant = partyClaimant;
		}
		else if (claimant.isEmpty())
		{
			claimant = partyClaimant;
		}
		long hostElapsed = Math.max(0L, now() - startsAt);
		recordPlacement(claimant, message.getCardIndex(), hostElapsed, message.getProof());
	}

	synchronized void onPlacement(RacePlacementMessage message)
	{
		if (message == null || localHost || !roundId.equals(message.getRoundId())
			|| message.getMemberId() != hostMemberId || hasPlaced(message.getPlayerName()))
		{
			return;
		}
		placements.add(new RacePlacement(cleanPlayerName(message.getPlayerName()), message.getPlace(),
			message.getPoints(), Math.max(0L, message.getElapsedMillis()), message.getCardIndex(), message.getProof()));
		dnfDeadlineAt = Math.max(dnfDeadlineAt, message.getDnfDeadlineAt());
		replaceScores(message.getScoreNames(), message.getScoreValues());
		if (normalize(localPlayerName()).equals(normalize(message.getPlayerName())))
		{
			localClaimSent = true;
		}
		gameMessage(ordinal(message.getPlace()) + " place: " + message.getPlayerName() + " in "
			+ formatDuration(message.getElapsedMillis()) + " (" + message.getPoints() + " points).");
	}

	synchronized void onRoundEnd(RaceRoundEndMessage message)
	{
		if (message == null || localHost)
		{
			return;
		}
		if (message.getRoundId() != null && message.getRoundId().equals(unresolvedRoundId))
		{
			// The round this client never managed to join is over, so stop asking the host to repeat it.
			unresolvedRoundId = "";
			gameMessage("The race this client could not join has ended.");
			return;
		}
		if (!roundId.equals(message.getRoundId()) || message.getMemberId() != hostMemberId)
		{
			return;
		}
		finishLocally(message.getEndedAt(), message.getReason(), message.getDnfPlayers());
	}

	synchronized void onScoreReset(RaceScoreResetMessage message)
	{
		if (message == null || isLocalSender(message.getMemberId()))
		{
			return;
		}
		scores.clear();
		roundsPlayed = 0;
		matchRound = 0;
		matchTotalRounds = 0;
		saveScores();
		gameMessage("The TCGG scoreboard was reset. A new match starts with the next pack.");
	}

	synchronized void requestPartyState()
	{
		if (partyService.isInParty() && !localHost)
		{
			partyService.send(new RaceStateRequestMessage());
		}
	}

	synchronized void onStateRequest(RaceStateRequestMessage message)
	{
		if (!localHost || message == null || isLocalSender(message.getMemberId())
			|| state == RaceSnapshot.State.IDLE)
		{
			return;
		}
		partyService.send(toStartMessage());
		for (RacePlacement placement : placements)
		{
			partyService.send(toPlacementMessage(placement));
		}
		if (state == RaceSnapshot.State.FINISHED)
		{
			RaceRoundEndMessage end = new RaceRoundEndMessage();
			end.setRoundId(roundId);
			end.setEndedAt(finishedAt);
			end.setReason("Round already complete");
			end.setDnfPlayers(new ArrayList<>(dnfPlayers));
			partyService.send(end);
		}
	}

	synchronized void onGameTick()
	{
		long now = now();
		if (localHost && isActive() && partyService.isInParty()
			&& now - lastStateBroadcastAt >= STATE_BROADCAST_INTERVAL_MILLIS)
		{
			partyService.send(toStartMessage());
			lastStateBroadcastAt = now;
		}
		else if (!localHost && isSyncLost() && partyService.isInParty()
			&& now - lastStateBroadcastAt >= STATE_BROADCAST_INTERVAL_MILLIS)
		{
			partyService.send(new RaceStateRequestMessage());
			lastStateBroadcastAt = now;
			log.debug("Requested host state to repair an idle synchronized round");
		}
		if (state == RaceSnapshot.State.COUNTDOWN && config.lockCountdownActions())
		{
			WorldPoint current = currentLocation();
			if (countdownOrigin != null && current != null && !countdownOrigin.equals(current))
			{
				countdownOrigin = current;
				if (localHost)
				{
					restartCountdown();
				}
				else if (!countdownHoldSent && partyService.isInParty())
				{
					countdownHoldSent = true;
					RaceCountdownHoldMessage hold = new RaceCountdownHoldMessage();
					hold.setRoundId(roundId);
					partyService.send(hold);
				}
			}
		}
		if (state == RaceSnapshot.State.COUNTDOWN && now >= startsAt)
		{
			state = RaceSnapshot.State.RUNNING;
			captureBaselineAndValidateStart();
			gameMessage(localInvalid ? "Race started, but your run is invalid: " + localInvalidReason : "Go! The TCGG timer has started.");
		}
		if (state == RaceSnapshot.State.RUNNING && now >= effectiveDeadline(endsAt, dnfDeadlineAt))
		{
			String reason = dnfDeadlineAt > 0L ? "DNF grace period expired" : "Time limit reached";
			if (localHost)
			{
				endHostedRound(reason);
			}
			else
			{
				finishLocally(effectiveDeadline(endsAt, dnfDeadlineAt), reason,
					unfinishedParticipants(participants, placements));
			}
		}
		if (canAttempt())
		{
			checkItemObjectives();
		}
		int tick = client.getTickCount();
		engagedNpcs.entrySet().removeIf(entry -> tick - entry.getValue() > NPC_ENGAGEMENT_TICKS);
	}

	synchronized void onItemContainerChanged(ItemContainerChanged event)
	{
		if (!canAttempt() || event == null)
		{
			return;
		}
		ItemContainer changed = event.getItemContainer();
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (changed == null || (!changed.equals(inventory) && !changed.equals(equipment)))
		{
			return;
		}
		checkItemObjectives();
	}

	private void checkItemObjectives()
	{
		if (!canAttempt())
		{
			return;
		}
		Map<Integer, Integer> current = carriedCounts();
		for (RaceCard card : cards)
		{
			if (card.getKind() != ObjectiveKind.ITEM)
			{
				continue;
			}
			for (Integer id : card.getTargetIds())
			{
				if (current.getOrDefault(id, 0) > itemBaseline.getOrDefault(id, 0))
				{
					tryComplete(card.getIndex(), "Obtained " + card.getDisplayName());
					return;
				}
			}
		}
	}

	synchronized void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (event == null)
		{
			return;
		}
		if (state == RaceSnapshot.State.COUNTDOWN && config.lockCountdownActions()
			&& isCountdownBlockedAction(event.getMenuAction()))
		{
			event.consume();
			if (!countdownLockNoticeShown)
			{
				countdownLockNoticeShown = true;
				gameMessage("Game actions are locked until the countdown reaches zero.");
			}
			return;
		}
		if (state != RaceSnapshot.State.RUNNING)
		{
			return;
		}
		String option = event.getMenuOption() == null ? "" : Text.removeTags(event.getMenuOption()).trim();
		String lower = option.toLowerCase(Locale.ROOT);
		if (config.invalidateWithdrawals() && (lower.startsWith("withdraw") || isGrandExchangeCollect(event, lower)))
		{
			invalidateLocal("Used a withdrawal or collection action");
		}
		if (config.invalidateGrandExchange() && isGrandExchangeAction(event))
		{
			invalidateLocal("Bought, sold, or collected at the Grand Exchange");
		}
		if (config.invalidateTrading() && lower.equals("trade with"))
		{
			invalidateLocal("Initiated a player trade");
		}
		if (!canAttempt())
		{
			return;
		}
		MenuEntry entry = event.getMenuEntry();
		NPC npc = entry == null ? null : entry.getNpc();
		if (npc == null || lower.equals("examine") || lower.equals("walk here") || lower.equals("attack"))
		{
			return;
		}
		for (RaceCard card : cards)
		{
			if (card.getKind() == ObjectiveKind.NPC && card.matchesId(npc.getId()))
			{
				tryComplete(card.getIndex(), option + " " + card.getDisplayName());
				return;
			}
		}
	}

	synchronized void onHitsplatApplied(HitsplatApplied event)
	{
		if (!canAttempt() || event == null || !(event.getActor() instanceof NPC))
		{
			return;
		}
		Hitsplat hitsplat = event.getHitsplat();
		NPC npc = (NPC) event.getActor();
		// Only a hit this player landed counts as engagement, so a kill stolen from another
		// racer's target cannot be claimed by simply clicking the monster first.
		if (hitsplat != null && hitsplat.isMine() && matchingMonster(npc.getId()) != null)
		{
			engagedNpcs.put(npc.getIndex(), client.getTickCount());
		}
	}

	synchronized void onActorDeath(ActorDeath event)
	{
		if (!canAttempt() || event == null || !(event.getActor() instanceof NPC))
		{
			return;
		}
		NPC npc = (NPC) event.getActor();
		RaceCard card = matchingMonster(npc.getId());
		Integer engagedAt = engagedNpcs.remove(npc.getIndex());
		if (card != null && engagedAt != null && client.getTickCount() - engagedAt <= NPC_ENGAGEMENT_TICKS)
		{
			tryComplete(card.getIndex(), "Killed " + card.getDisplayName());
		}
	}

	synchronized void manualEndRound()
	{
		if (localHost && isActive())
		{
			endHostedRound("Ended by host");
		}
	}

	/**
	 * Abandons the round the local client is hosting. Unlike ending it, nobody is scored: any
	 * points already awarded this round are handed back and nobody is marked DNF.
	 */
	synchronized void cancelRound()
	{
		if (!localHost || !isActive())
		{
			return;
		}
		for (Map.Entry<String, Integer> award : roundAwards.entrySet())
		{
			addScore(award.getKey(), -award.getValue());
		}
		saveScores();
		String cancelled = roundId;
		boolean inParty = partyService.isInParty();
		clearRound();
		if (inParty)
		{
			RaceRoundCancelMessage message = new RaceRoundCancelMessage();
			message.setRoundId(cancelled);
			for (Map.Entry<String, Integer> score : sortedScores())
			{
				message.getScoreNames().add(score.getKey());
				message.getScoreValues().add(score.getValue());
			}
			partyService.send(message);
		}
		gameMessage("Round cancelled. No points were awarded.");
	}

	synchronized void onRoundCancel(RaceRoundCancelMessage message)
	{
		if (message == null || localHost || message.getRoundId() == null
			|| !(message.getRoundId().equals(roundId) || message.getRoundId().equals(unresolvedRoundId)))
		{
			return;
		}
		clearRound();
		replaceScores(message.getScoreNames(), message.getScoreValues());
		gameMessage("The host cancelled the round. No points were awarded.");
	}

	synchronized void resetScores()
	{
		scores.clear();
		roundsPlayed = 0;
		matchRound = 0;
		matchTotalRounds = 0;
		saveScores();
		if (partyService.isInParty())
		{
			RaceScoreResetMessage message = new RaceScoreResetMessage();
			message.setResetAt(now());
			partyService.send(message);
		}
		gameMessage("TCGG scores reset.");
	}

	synchronized RaceSnapshot snapshot()
	{
		List<String> visibleParticipants = state == RaceSnapshot.State.IDLE
			? captureParticipants() : participants;
		return new RaceSnapshot(roundId, state, startsAt,
			state == RaceSnapshot.State.FINISHED ? finishedAt : endsAt,
			dnfDeadlineAt, cards, placements, visibleParticipants, dnfPlayers, scores,
			localInvalid, localInvalidReason, isSyncLost(),
			new ArrayList<>(readyPlayers), isReady(localPlayerName()), matchState(), !pendingPack.isEmpty());
	}

	private void beginRound(String id, long start, long end, List<RaceCard> roundCards,
		List<String> roundParticipants, long hostId, boolean host, int round, int scheduledRounds)
	{
		matchRound = round;
		matchTotalRounds = scheduledRounds;
		// The host owns the match count, so a guest adopts it rather than trusting its own history.
		roundsPlayed = Math.max(0, round - 1);
		roundId = id;
		startsAt = start > 0L ? start : now();
		endsAt = Math.max(startsAt + 1_000L, end);
		finishedAt = 0L;
		dnfDeadlineAt = 0L;
		cards = Collections.unmodifiableList(new ArrayList<>(roundCards));
		participants = immutableUniqueNames(roundParticipants);
		if (participants.isEmpty())
		{
			participants = Collections.singletonList(localPlayerName());
		}
		placements.clear();
		dnfPlayers.clear();
		itemBaseline.clear();
		engagedNpcs.clear();
		hostMemberId = hostId;
		countdownOrigin = currentLocation();
		localHost = host;
		baselineCaptured = false;
		localClaimSent = false;
		localInvalid = false;
		countdownLockNoticeShown = false;
		countdownHoldSent = false;
		spectatorNoticeShown = false;
		localInvalidReason = "";
		unresolvedRoundId = "";
		readyPlayers.clear();
		roundAwards.clear();
		pendingPack = Collections.emptyList();
		lastStateBroadcastAt = host ? now() : 0L;
		state = RaceSnapshot.State.COUNTDOWN;
	}

	private WorldPoint currentLocation()
	{
		Player player = client.getLocalPlayer();
		return player == null ? null : player.getWorldLocation();
	}

	private void restartCountdown()
	{
		long duration = Math.max(1_000L, endsAt - startsAt);
		startsAt = now() + Math.max(0, config.countdownSeconds()) * 1_000L;
		endsAt = startsAt + duration;
		countdownOrigin = currentLocation();
		countdownHoldSent = false;
		lastStateBroadcastAt = now();
		if (partyService.isInParty())
		{
			partyService.send(toStartMessage());
		}
	}

	private RaceRoundStartMessage toStartMessage()
	{
		RaceRoundStartMessage message = new RaceRoundStartMessage();
		message.setRoundId(roundId);
		message.setStartsAt(startsAt);
		message.setEndsAt(endsAt);
		message.setMatchRound(matchRound);
		message.setTotalRounds(matchTotalRounds);
		message.setParticipants(new ArrayList<>(participants));
		for (RaceCard card : cards)
		{
			message.getCardNames().add(card.getCardName());
		}
		return message;
	}

	private List<RaceCard> cardsFrom(RaceRoundStartMessage message)
	{
		List<String> names = message.getCardNames();
		if (names == null || names.size() != 5)
		{
			return Collections.emptyList();
		}
		List<RaceCard> resolved = catalogService.resolvePack(names);
		if (resolved.size() != 5)
		{
			return Collections.emptyList();
		}
		for (RaceCard card : resolved)
		{
			// A card this client cannot target would leave the racer with an objective they can never claim.
			if (card.getKind() == ObjectiveKind.UNKNOWN || card.getTargetIds().isEmpty())
			{
				return Collections.emptyList();
			}
		}
		return resolved;
	}

	private void captureBaselineAndValidateStart()
	{
		itemBaseline.clear();
		itemBaseline.putAll(carriedCounts());
		baselineCaptured = true;
		if (config.requireKandarinMonastery())
		{
			Player player = client.getLocalPlayer();
			WorldPoint location = player == null ? null : player.getWorldLocation();
			if (location == null || location.getPlane() != KANDARIN_MONASTERY.getPlane()
				|| location.distanceTo(KANDARIN_MONASTERY) > config.monasteryRadius())
			{
				invalidateLocal("Not at Kandarin Monastery when the timer started");
			}
		}
		if (config.validateStarterLoadout())
		{
			List<String> carriedNames = new ArrayList<>();
			for (Item item : carriedItems())
			{
				if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
				{
					continue;
				}
				String name = itemManager.getItemComposition(item.getId()).getName();
				carriedNames.add(name);
				if (!isAllowedStarter(name))
				{
					invalidateLocal("Started with prohibited item: " + name);
					break;
				}
			}
			if (!localInvalid && config.requireEveryStarterItem())
			{
				for (String raw : config.requiredStarterItems().split(","))
				{
					String rule = normalize(raw);
					if (!rule.isEmpty() && carriedNames.stream().noneMatch(name -> matchesStarterRule(name, rule)))
					{
						invalidateLocal("Missing required starter item: " + raw.trim());
						break;
					}
				}
			}
		}
	}

	private boolean isAllowedStarter(String itemName)
	{
		for (String raw : config.allowedStarterItems().split(","))
		{
			String rule = normalize(raw);
			if (matchesStarterRule(itemName, rule))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean matchesStarterRule(String itemName, String rule)
	{
		String normalized = normalize(itemName);
		return rule.endsWith("*")
			? normalized.startsWith(rule.substring(0, rule.length() - 1))
			: normalized.equals(rule);
	}

	/** True for any click inside a Grand Exchange offer, side, or collection interface. */
	private static boolean isGrandExchangeAction(MenuOptionClicked event)
	{
		MenuEntry entry = event.getMenuEntry();
		if (entry == null)
		{
			return false;
		}
		int group = WidgetUtil.componentToInterface(entry.getParam1());
		return group == InterfaceID.GE_OFFERS || group == InterfaceID.GE_OFFERS_SIDE
			|| group == InterfaceID.GE_COLLECT;
	}

	private static boolean isGrandExchangeCollect(MenuOptionClicked event, String lowerOption)
	{
		if (!lowerOption.startsWith("collect"))
		{
			return false;
		}
		MenuEntry entry = event.getMenuEntry();
		if (entry == null)
		{
			return false;
		}
		int group = WidgetUtil.componentToInterface(entry.getParam1());
		return group == InterfaceID.GE_COLLECT || group == InterfaceID.GE_OFFERS;
	}

	static boolean isCountdownBlockedAction(MenuAction action)
	{
		if (action == null)
		{
			return false;
		}
		switch (action)
		{
			case CANCEL:
			case EXAMINE_ITEM:
			case EXAMINE_ITEM_GROUND:
			case EXAMINE_NPC:
			case EXAMINE_OBJECT:
			case EXAMINE_WORLD_ENTITY:
			case RUNELITE:
			case RUNELITE_HIGH_PRIORITY:
			case RUNELITE_INFOBOX:
			case RUNELITE_LOW_PRIORITY:
			case RUNELITE_OVERLAY:
			case RUNELITE_OVERLAY_CONFIG:
			case RUNELITE_PLAYER:
			case RUNELITE_WIDGET:
			case SET_HEADING:
			case WIDGET_CLOSE:
				return false;
			default:
				return true;
		}
	}

	private List<Item> carriedItems()
	{
		List<Item> result = new ArrayList<>();
		for (int inventoryId : new int[]{InventoryID.INV, InventoryID.WORN})
		{
			ItemContainer container = client.getItemContainer(inventoryId);
			if (container != null && container.getItems() != null)
			{
				result.addAll(Arrays.asList(container.getItems()));
			}
		}
		return result;
	}

	private Map<Integer, Integer> carriedCounts()
	{
		Map<Integer, Integer> counts = new HashMap<>();
		for (Item item : carriedItems())
		{
			if (item != null && item.getId() > 0 && item.getQuantity() > 0)
			{
				counts.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
		return counts;
	}

	private void tryComplete(int cardIndex, String proof)
	{
		if (!canAttempt() || cardIndex < 0 || cardIndex >= cards.size())
		{
			return;
		}
		if (!isParticipant(localPlayerName()))
		{
			// The host only scores players it listed when the round began, so say so rather than
			// sending a claim that would be dropped without a word and lock this racer out.
			if (!spectatorNoticeShown)
			{
				spectatorNoticeShown = true;
				gameMessage("You joined after this round started, so your completions are not scored."
					+ " You will be included in the next round.");
			}
			return;
		}
		long elapsed = Math.max(0L, now() - startsAt);
		String playerName = localPlayerName();
		localClaimSent = true;
		if (localHost)
		{
			recordPlacement(playerName, cardIndex, elapsed, proof);
		}
		else
		{
			RaceClaimMessage message = new RaceClaimMessage();
			message.setRoundId(roundId);
			message.setPlayerName(playerName);
			message.setCardIndex(cardIndex);
			message.setElapsedMillis(elapsed);
			message.setProof(proof);
			partyService.send(message);
			gameMessage("Completion sent to the race host: " + proof + ".");
		}
	}

	private void recordPlacement(String playerName, int cardIndex, long elapsed, String proof)
	{
		String cleanName = cleanPlayerName(playerName);
		if (cleanName.isEmpty() || hasPlaced(cleanName) || !isParticipant(cleanName)
			|| now() >= effectiveDeadline(endsAt, dnfDeadlineAt))
		{
			return;
		}
		int place = placements.size() + 1;
		int points = pointsFor(place);
		RacePlacement placement = new RacePlacement(cleanName, place, points, Math.max(0L, elapsed),
			cardIndex, proof == null ? "" : proof);
		placements.add(placement);
		if (place == 1)
		{
			dnfDeadlineAt = Math.min(endsAt, now()
				+ Math.max(1, config.dnfGraceMinutes()) * 60_000L);
		}
		addScore(cleanName, points);
		roundAwards.merge(cleanName, points, Integer::sum);
		saveScores();
		if (partyService.isInParty())
		{
			partyService.send(toPlacementMessage(placement));
		}
		gameMessage(ordinal(place) + " place: " + cleanName + " in " + formatDuration(elapsed)
			+ " (" + points + " points).");
		if (unfinishedParticipants(participants, placements).isEmpty())
		{
			endHostedRound("All players finished");
		}
	}

	private RacePlacementMessage toPlacementMessage(RacePlacement placement)
	{
		RacePlacementMessage message = new RacePlacementMessage();
		message.setRoundId(roundId);
		message.setPlayerName(placement.getPlayerName());
		message.setPlace(placement.getPlace());
		message.setPoints(placement.getPoints());
		message.setElapsedMillis(placement.getElapsedMillis());
		message.setCardIndex(placement.getCardIndex());
		message.setProof(placement.getProof());
		message.setDnfDeadlineAt(dnfDeadlineAt);
		for (Map.Entry<String, Integer> score : sortedScores())
		{
			message.getScoreNames().add(score.getKey());
			message.getScoreValues().add(score.getValue());
		}
		return message;
	}

	private void endHostedRound(String reason)
	{
		long now = now();
		List<String> unfinished = unfinishedParticipants(participants, placements);
		finishLocally(now, reason, unfinished);
		if (partyService.isInParty())
		{
			RaceRoundEndMessage message = new RaceRoundEndMessage();
			message.setRoundId(roundId);
			message.setEndedAt(now);
			message.setReason(reason);
			message.setDnfPlayers(new ArrayList<>(unfinished));
			partyService.send(message);
		}
	}

	private void finishLocally(long endedAt, String reason, List<String> unfinished)
	{
		state = RaceSnapshot.State.FINISHED;
		finishedAt = endedAt > 0L ? endedAt : now();
		dnfPlayers.clear();
		dnfPlayers.addAll(immutableUniqueNames(unfinished));
		roundsPlayed = Math.max(roundsPlayed, matchRound);
		saveScores();
		gameMessage("Round over: " + (reason == null ? "finished" : reason) + ".");
		if (isMatchComplete())
		{
			gameMessage("That was round " + matchRound + " of " + matchTotalRounds + ". "
				+ matchResultLine());
		}
	}

	private void invalidateLocal(String reason)
	{
		if (!localInvalid)
		{
			localInvalid = true;
			localInvalidReason = reason;
			gameMessage("Your current run is invalid: " + reason + ".");
		}
	}

	private boolean canAttempt()
	{
		return state == RaceSnapshot.State.RUNNING && baselineCaptured && !localInvalid && !localClaimSent;
	}

	private RaceCard matchingMonster(int npcId)
	{
		for (RaceCard card : cards)
		{
			if (card.getKind() == ObjectiveKind.MONSTER && card.matchesId(npcId))
			{
				return card;
			}
		}
		return null;
	}

	private MatchState matchState()
	{
		List<Map.Entry<String, Integer>> ranked = sortedScores();
		Map.Entry<String, Integer> leader = ranked.isEmpty() ? null : ranked.get(0);
		return new MatchState(matchRound, scheduledRounds(), roundsPlayed, isMatchComplete(),
			leader == null ? "" : leader.getKey(), leader == null ? 0 : leader.getValue());
	}

	/** The host's schedule while a match is under way, otherwise this client's own setting. */
	private int scheduledRounds()
	{
		return matchTotalRounds > 0 ? matchTotalRounds : Math.max(0, config.totalRounds());
	}

	private boolean isMatchComplete()
	{
		int scheduled = scheduledRounds();
		return scheduled > 0 && roundsPlayed >= scheduled;
	}

	private String matchResultLine()
	{
		List<Map.Entry<String, Integer>> ranked = sortedScores();
		if (ranked.isEmpty())
		{
			return "Nobody scored.";
		}
		Map.Entry<String, Integer> leader = ranked.get(0);
		long tied = ranked.stream().filter(entry -> entry.getValue().equals(leader.getValue())).count();
		return tied > 1
			? "It is a " + tied + "-way tie on " + leader.getValue() + " points."
			: leader.getKey() + " wins with " + leader.getValue() + " points.";
	}

	/** True when a synchronized round is running that this client could not resolve into objectives. */
	private boolean isSyncLost()
	{
		return !unresolvedRoundId.isEmpty() && state == RaceSnapshot.State.IDLE;
	}

	private boolean isActive()
	{
		return state == RaceSnapshot.State.COUNTDOWN || state == RaceSnapshot.State.RUNNING;
	}

	private boolean hasPlaced(String playerName)
	{
		String wanted = normalize(playerName);
		for (RacePlacement placement : placements)
		{
			if (normalize(placement.getPlayerName()).equals(wanted))
			{
				return true;
			}
		}
		return false;
	}

	private int scoringPlaces()
	{
		return Math.max(1, Math.min(5, config.scoringPlaces()));
	}

	private int pointsFor(int place)
	{
		if (place > scoringPlaces())
		{
			return 0;
		}
		switch (place)
		{
			case 1: return config.firstPoints();
			case 2: return config.secondPoints();
			case 3: return config.thirdPoints();
			case 4: return config.fourthPoints();
			case 5: return config.fifthPoints();
			default: return 0;
		}
	}

	private void addScore(String playerName, int points)
	{
		for (String existing : new ArrayList<>(scores.keySet()))
		{
			if (normalize(existing).equals(normalize(playerName)))
			{
				scores.put(existing, Math.max(0, scores.get(existing) + points));
				return;
			}
		}
		scores.put(playerName, Math.max(0, points));
	}

	private List<Map.Entry<String, Integer>> sortedScores()
	{
		List<Map.Entry<String, Integer>> sorted = new ArrayList<>(scores.entrySet());
		sorted.sort(Map.Entry.<String, Integer>comparingByValue(Comparator.reverseOrder())
			.thenComparing(Map.Entry.comparingByKey(String.CASE_INSENSITIVE_ORDER)));
		return sorted;
	}

	private void replaceScores(List<String> names, List<Integer> values)
	{
		if (names == null || values == null || names.size() != values.size())
		{
			return;
		}
		scores.clear();
		for (int i = 0; i < names.size(); i++)
		{
			if (names.get(i) != null && values.get(i) != null)
			{
				scores.put(names.get(i), Math.max(0, values.get(i)));
			}
		}
		saveScores();
	}

	private boolean isLocalSender(long memberId)
	{
		PartyMember local = partyService.getLocalMember();
		return local != null && local.getMemberId() == memberId;
	}

	private String partyName(long memberId)
	{
		PartyMember member = partyService.getMemberById(memberId);
		return member == null || member.getDisplayName() == null ? "A party member" : member.getDisplayName();
	}

	private String localPlayerName()
	{
		Player player = client.getLocalPlayer();
		return player == null ? "Local player" : cleanPlayerName(player.getName());
	}

	private List<String> captureParticipants()
	{
		List<String> names = new ArrayList<>();
		if (partyService.isInParty())
		{
			for (PartyMember member : partyService.getMembers())
			{
				if (member != null && member.isLoggedIn())
				{
					names.add(member.getDisplayName());
				}
			}
		}
		names.add(localPlayerName());
		return immutableUniqueNames(names);
	}

	private boolean isParticipant(String playerName)
	{
		String wanted = normalize(playerName);
		for (String participant : participants)
		{
			if (normalize(participant).equals(wanted))
			{
				return true;
			}
		}
		return false;
	}

	private static List<String> immutableUniqueNames(List<String> names)
	{
		List<String> result = new ArrayList<>();
		if (names != null)
		{
			for (String name : names)
			{
				String clean = cleanPlayerName(name);
				if (!clean.isEmpty() && result.stream().noneMatch(existing -> normalize(existing).equals(normalize(clean))))
				{
					result.add(clean);
				}
			}
		}
		return Collections.unmodifiableList(result);
	}

	static List<String> unfinishedParticipants(List<String> roundParticipants, List<RacePlacement> roundPlacements)
	{
		List<String> result = new ArrayList<>();
		for (String participant : immutableUniqueNames(roundParticipants))
		{
			boolean finished = false;
			if (roundPlacements != null)
			{
				for (RacePlacement placement : roundPlacements)
				{
					if (placement != null && normalize(placement.getPlayerName()).equals(normalize(participant)))
					{
						finished = true;
						break;
					}
				}
			}
			if (!finished)
			{
				result.add(participant);
			}
		}
		return result;
	}

	static long effectiveDeadline(long roundEndsAt, long graceEndsAt)
	{
		return graceEndsAt > 0L ? Math.min(roundEndsAt, graceEndsAt) : roundEndsAt;
	}

	private static String cleanPlayerName(String value)
	{
		return value == null ? "" : Text.removeTags(value).trim();
	}

	private static String normalize(String value)
	{
		return cleanPlayerName(value).toLowerCase(Locale.ROOT);
	}

	private void gameMessage(String message)
	{
		client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", CHAT_PREFIX + message, null);
	}

	private void loadScores()
	{
		try
		{
			String stored = configManager.getRSProfileConfiguration(TcgRaceConfig.GROUP, SCORE_KEY);
			ScoreStore decoded = stored == null ? null : gson.fromJson(stored, ScoreStore.class);
			if (decoded != null)
			{
				replaceScores(decoded.names, decoded.values);
				roundsPlayed = Math.max(0, decoded.roundsPlayed);
			}
		}
		catch (RuntimeException ex)
		{
			log.debug("Unable to load TCGG scores", ex);
		}
	}

	private void saveScores()
	{
		try
		{
			ScoreStore store = new ScoreStore();
			for (Map.Entry<String, Integer> entry : sortedScores())
			{
				store.names.add(entry.getKey());
				store.values.add(entry.getValue());
			}
			store.roundsPlayed = roundsPlayed;
			configManager.setRSProfileConfiguration(TcgRaceConfig.GROUP, SCORE_KEY, gson.toJson(store));
		}
		catch (RuntimeException ex)
		{
			log.debug("Unable to save TCGG scores", ex);
		}
	}

	private void clearRound()
	{
		cards = Collections.emptyList();
		participants = Collections.emptyList();
		placements.clear();
		dnfPlayers.clear();
		itemBaseline.clear();
		engagedNpcs.clear();
		roundId = "";
		state = RaceSnapshot.State.IDLE;
		startsAt = 0L;
		endsAt = 0L;
		dnfDeadlineAt = 0L;
		finishedAt = 0L;
		hostMemberId = 0L;
		countdownOrigin = null;
		localHost = false;
		baselineCaptured = false;
		localClaimSent = false;
		localInvalid = false;
		countdownLockNoticeShown = false;
		countdownHoldSent = false;
		spectatorNoticeShown = false;
		localInvalidReason = "";
		unresolvedRoundId = "";
		readyPlayers.clear();
		roundAwards.clear();
		pendingPack = Collections.emptyList();
		matchRound = 0;
		matchTotalRounds = 0;
		lastStateBroadcastAt = 0L;
	}

	static String formatDuration(long millis)
	{
		long totalTenths = Math.max(0L, millis) / 100L;
		long hours = totalTenths / 36_000L;
		long minutes = (totalTenths / 600L) % 60L;
		long seconds = (totalTenths / 10L) % 60L;
		long tenths = totalTenths % 10L;
		return hours > 0L
			? String.format(Locale.ROOT, "%d:%02d:%02d.%d", hours, minutes, seconds, tenths)
			: String.format(Locale.ROOT, "%02d:%02d.%d", minutes, seconds, tenths);
	}

	static String ordinal(int place)
	{
		if (place % 100 >= 11 && place % 100 <= 13)
		{
			return place + "th";
		}
		switch (place % 10)
		{
			case 1: return place + "st";
			case 2: return place + "nd";
			case 3: return place + "rd";
			default: return place + "th";
		}
	}

	private static final class ScoreStore
	{
		private List<String> names = new ArrayList<>();
		private List<Integer> values = new ArrayList<>();
		private int roundsPlayed;
	}
}

package com.tcgrace;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.tcgrace.model.ObjectiveKind;
import com.tcgrace.model.RaceCard;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.game.NPCManager;

/** Read-only resolver for the live catalog already cached by OSRS TCG. */
@Slf4j
@Singleton
public class TcgCatalogService
{
	private static final Path CATALOG_PATH = Path.of(
		RuneLite.RUNELITE_DIR.getAbsolutePath(), "OSRS-TCG", "catalog", "cards.live.json");

	private final Gson gson;
	private final NPCManager npcManager;
	private volatile Map<String, CatalogCard> cards = Collections.emptyMap();
	private volatile long loadedModifiedAt = -1L;

	@Inject
	TcgCatalogService(Gson gson, NPCManager npcManager)
	{
		this.gson = gson;
		this.npcManager = npcManager;
	}

	/** Performs disk I/O and must only be called from a background executor. */
	void refreshFromDisk()
	{
		try
		{
			if (!Files.isRegularFile(CATALOG_PATH))
			{
				return;
			}
			long modified = Files.getLastModifiedTime(CATALOG_PATH).toMillis();
			if (modified == loadedModifiedAt && !cards.isEmpty())
			{
				return;
			}
			String json = Files.readString(CATALOG_PATH, StandardCharsets.UTF_8);
			JsonObject root = gson.fromJson(json, JsonObject.class);
			Map<String, CatalogCard> parsed = parse(root);
			if (!parsed.isEmpty())
			{
				cards = Collections.unmodifiableMap(parsed);
				loadedModifiedAt = modified;
				log.debug("Loaded {} OSRS TCG race targets", cards.size());
			}
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Unable to read the OSRS TCG live catalog", ex);
		}
	}

	List<RaceCard> resolvePack(List<String> pulledNames)
	{
		List<RaceCard> result = new ArrayList<>();
		if (pulledNames == null)
		{
			return result;
		}
		for (int index = 0; index < pulledNames.size(); index++)
		{
			String pulledName = pulledNames.get(index) == null ? "" : pulledNames.get(index).trim();
			CatalogCard card = cards.get(normalize(pulledName));
			if (card == null)
			{
				result.add(new RaceCard(index, pulledName, pulledName, ObjectiveKind.UNKNOWN, Collections.emptyList()));
				continue;
			}
			ObjectiveKind kind = card.npc ? npcKind(card.ids) : ObjectiveKind.ITEM;
			result.add(new RaceCard(index, pulledName, card.displayName, kind, card.ids));
		}
		return result;
	}

	private ObjectiveKind npcKind(List<Integer> ids)
	{
		for (Integer id : ids)
		{
			if (id == null)
			{
				continue;
			}
			try
			{
				if (npcManager.getHealth(id) > 0)
				{
					return ObjectiveKind.MONSTER;
				}
			}
			catch (RuntimeException ignored)
			{
				// NPC stats load asynchronously; an unresolved stat safely falls back to interaction.
			}
		}
		return ObjectiveKind.NPC;
	}

	private static Map<String, CatalogCard> parse(JsonObject root)
	{
		if (root == null)
		{
			return Collections.emptyMap();
		}
		Map<String, CatalogCard> result = new LinkedHashMap<>();
		Set<String> itemNames = new LinkedHashSet<>();
		JsonArray items = array(root, "items");
		for (JsonElement element : items)
		{
			CatalogCard card = parseCard(element, false);
			if (card != null)
			{
				String key = normalize(card.displayName);
				itemNames.add(key);
				result.putIfAbsent(key, card);
			}
		}
		for (JsonElement element : array(root, "npcs"))
		{
			CatalogCard card = parseCard(element, true);
			if (card == null)
			{
				continue;
			}
			String displayKey = normalize(card.displayName);
			String storageKey = itemNames.contains(displayKey) && !card.ids.isEmpty()
				? "npc:" + card.ids.get(0) : displayKey;
			result.putIfAbsent(storageKey, card);
			if (!itemNames.contains(displayKey))
			{
				result.putIfAbsent(displayKey, card);
			}
		}
		return result;
	}

	private static CatalogCard parseCard(JsonElement element, boolean npc)
	{
		if (element == null || !element.isJsonObject())
		{
			return null;
		}
		JsonObject raw = element.getAsJsonObject();
		String name = text(raw, "name");
		if (name.isEmpty())
		{
			return null;
		}
		Set<Integer> ids = new LinkedHashSet<>();
		addId(raw.get("id"), ids);
		JsonObject tcg = object(raw, "tcg");
		for (JsonElement variant : array(tcg, "variants"))
		{
			if (variant != null && variant.isJsonObject())
			{
				addId(variant.getAsJsonObject().get("id"), ids);
			}
		}
		return new CatalogCard(name, npc, new ArrayList<>(ids));
	}

	private static void addId(JsonElement value, Set<Integer> ids)
	{
		if (value != null && value.isJsonPrimitive() && value.getAsJsonPrimitive().isNumber())
		{
			ids.add(value.getAsInt());
		}
	}

	private static JsonArray array(JsonObject object, String key)
	{
		return object != null && object.has(key) && object.get(key).isJsonArray()
			? object.getAsJsonArray(key) : new JsonArray();
	}

	private static JsonObject object(JsonObject object, String key)
	{
		return object != null && object.has(key) && object.get(key).isJsonObject()
			? object.getAsJsonObject(key) : new JsonObject();
	}

	private static String text(JsonObject object, String key)
	{
		if (object == null || !object.has(key) || !object.get(key).isJsonPrimitive())
		{
			return "";
		}
		return object.get(key).getAsString().trim();
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}

	private static final class CatalogCard
	{
		private final String displayName;
		private final boolean npc;
		private final List<Integer> ids;

		private CatalogCard(String displayName, boolean npc, List<Integer> ids)
		{
			this.displayName = displayName;
			this.npc = npc;
			this.ids = ids;
		}
	}
}

