/** Detects exact five-card pack writes from OSRS TCG without changing its state. */
@Slf4j
@Singleton
public class TcgPackDetector
{
	private static final String PREFIX_V3 = "RLTCG_v3:";
	private static final String PREFIX_V2 = "RLTCG_v2:";
	private static final int EXPECTED_PACK_SIZE = 5;
	private static final long ANNOUNCEMENT_WINDOW_MILLIS = TimeUnit.MINUTES.toMillis(2L);
	private static final long CHAT_DEDUP_WINDOW_MILLIS = TimeUnit.MINUTES.toMillis(10L);
	private static final String LOCAL_PULL_PREFIX = "[OSRS TCG] You just added ";
	private static final String LOCAL_PULL_SUFFIX = " to your collection!";
	private static final byte[] XOR_SALT = {
		0x52, 0x4c, 0x54, 0x43, 0x47, 0x7c, 0x6f, 0x73,
		0x72, 0x73, 0x2d, 0x74, 0x63, 0x67, 0x21
	};

	private final Gson gson;
	private final ClientThread clientThread;
	private final ScheduledExecutorService scheduler;
	private final TcgCatalogService catalogService;
	private ScheduledFuture<?> pollTask;
	private List<Path> savePaths = Collections.emptyList();
	private long previousOpenedPacks;
	private Map<String, StoredCardInstance> previousInstances = Collections.emptyMap();
	private boolean baselined;
	private Consumer<List<String>> packConsumer;
	private List<String> latestSavedPack = Collections.emptyList();
	private final List<String> announcedPulls = new ArrayList<>();
	private final List<RecentChatPack> recentChatPacks = new ArrayList<>();
	private long announcementStartedAt;

	@Inject
	TcgPackDetector(Gson gson, ClientThread clientThread, ScheduledExecutorService scheduler,
		TcgCatalogService catalogService)
	{
		this.gson = gson;
		this.clientThread = clientThread;
		this.scheduler = scheduler;
		this.catalogService = catalogService;
	}

	synchronized void start(Consumer<List<String>> consumer)
	{
		packConsumer = consumer;
		if (pollTask == null)
		{
			pollTask = scheduler.scheduleWithFixedDelay(this::pollSafely, 0L, 1L, TimeUnit.SECONDS);
		}
	}

	synchronized void stop()
	{
		if (pollTask != null)
		{
			pollTask.cancel(true);
			pollTask = null;
		}
		packConsumer = null;
		resetBaseline();
	}

	synchronized void useAccount(long accountHash, String profileKey)
	{
		Path root = Path.of(RuneLite.RUNELITE_DIR.getAbsolutePath(), "OSRS-TCG");
		List<Path> candidates = new ArrayList<>();
		if (accountHash != -1L)
		{
			String accountDirectory = sha256(Long.toString(accountHash));
			if (accountDirectory != null)
			{
				candidates.add(root.resolve("profiles").resolve(accountDirectory).resolve("tcg.save"));
			}
		}
		String legacyDirectory = profileKey == null || profileKey.isEmpty() ? null : sha256(profileKey);
		if (legacyDirectory != null)
		{
			candidates.add(root.resolve("backups").resolve(legacyDirectory).resolve("tcg.save"));
		}
		candidates.add(root.resolve("backups").resolve("default").resolve("tcg.save"));
		savePaths = List.copyOf(candidates);
		resetBaseline();
	}

	synchronized void onChatMessage(ChatMessage event)
	{
		if (event == null || event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String cardName = parseLocalPullMessage(event.getMessage());
		if (cardName == null)
		{
			String plain = Text.removeTags(event.getMessage() == null ? "" : event.getMessage()).trim();
			if (plain.contains("OSRS TCG") || plain.startsWith("Opened pack"))
			{
				log.debug("Observed an OSRS TCG game message that was not a card reveal");
			}
			return;
		}
		long now = System.currentTimeMillis();
		if (announcedPulls.isEmpty() || now - announcementStartedAt > ANNOUNCEMENT_WINDOW_MILLIS)
		{
			announcedPulls.clear();
			announcementStartedAt = now;
		}
		announcedPulls.add(cardName);
		log.debug("Captured OSRS TCG reveal {} of {}", announcedPulls.size(), EXPECTED_PACK_SIZE);
		if (announcedPulls.size() < EXPECTED_PACK_SIZE)
		{
			return;
		}

		List<String> pack = List.copyOf(announcedPulls);
		announcedPulls.clear();
		announcementStartedAt = 0L;
		pruneRecentChatPacks(now);
		recentChatPacks.add(new RecentChatPack(packSignature(pack), now));
		Consumer<List<String>> consumer = packConsumer;
		if (consumer != null)
		{
			log.info("Detected an OSRS TCG pack from five local reveal messages");
			clientThread.invokeLater(() -> consumer.accept(pack));
		}
	}

	synchronized List<String> latestSavedPack()
	{
		if (latestSavedPack.size() != EXPECTED_PACK_SIZE)
		{
			return Collections.emptyList();
		}
		return List.copyOf(latestSavedPack);
	}

	synchronized boolean hasLatestSavedPack()
	{
		return latestSavedPack.size() == EXPECTED_PACK_SIZE;
	}

	private synchronized void resetBaseline()
	{
		baselined = false;
		previousOpenedPacks = 0L;
		previousInstances = Collections.emptyMap();
		latestSavedPack = Collections.emptyList();
		announcedPulls.clear();
		announcementStartedAt = 0L;
	}

	private void pollSafely()
	{
		try
		{
			catalogService.refreshFromDisk();
			poll();
		}
		catch (RuntimeException ex)
		{
			log.debug("OSRS TCG pack poll failed", ex);
		}
	}

	private void poll()
	{
		List<Path> currentPaths;
		synchronized (this)
		{
			currentPaths = savePaths;
		}
		Path currentPath = null;
		for (Path candidate : currentPaths)
		{
			if (Files.isRegularFile(candidate))
			{
				currentPath = candidate;
				break;
			}
		}
		if (currentPath == null)
		{
			return;
		}
		StoredState state;
		try
		{
			String encoded = Files.readString(currentPath, StandardCharsets.UTF_8).trim();
			String json = decode(encoded);
			state = json.isEmpty() ? null : gson.fromJson(json, StoredState.class);
		}
		catch (IOException | RuntimeException ex)
		{
			log.debug("Unable to read OSRS TCG pack state", ex);
			return;
		}
		if (state == null)
		{
			return;
		}

		Map<String, StoredCardInstance> current = index(state.expandedInstances());
		List<List<String>> packs;
		synchronized (this)
		{
			latestSavedPack = latestCompletePack(current.values());
			if (!baselined)
			{
				previousOpenedPacks = state.openedPacks;
				previousInstances = current;
				baselined = true;
				return;
			}
			if (state.openedPacks <= previousOpenedPacks)
			{
				previousInstances = current;
				return;
			}
			packs = detectPacks(previousInstances, current);
			if (packs.isEmpty())
			{
				// OSRS TCG can persist the pack counter just before its card rows.
				return;
			}
			previousOpenedPacks = state.openedPacks;
			previousInstances = current;
		}
		// A delayed save can contain several packs opened since the last poll. Only the
		// newest pack is the one the player just opened and should begin a race.
		if (packs.size() > 1)
		{
			packs = Collections.singletonList(packs.get(packs.size() - 1));
		}
		for (List<String> pack : packs)
		{
			if (consumeRecentChatPack(pack))
			{
				log.debug("Ignored delayed OSRS TCG save update already detected from reveal messages");
				continue;
			}
			Consumer<List<String>> consumer;
			synchronized (this)
			{
				consumer = packConsumer;
			}
			if (consumer != null)
			{
				List<String> immutable = List.copyOf(pack);
				log.debug("Detected an OSRS TCG pack from its saved collection");
				clientThread.invokeLater(() -> consumer.accept(immutable));
			}
		}
	}

	static List<String> latestCompletePack(Iterable<StoredCardInstance> instances)
	{
		Map<Long, List<String>> byPullTime = new LinkedHashMap<>();
		for (StoredCardInstance instance : instances)
		{
			if (instance != null && instance.pulledAt > 0L && instance.cardName != null)
			{
				byPullTime.computeIfAbsent(instance.pulledAt, ignored -> new ArrayList<>())
					.add(instance.cardName);
			}
		}
		long latestTime = Long.MIN_VALUE;
		List<String> latest = Collections.emptyList();
		for (Map.Entry<Long, List<String>> entry : byPullTime.entrySet())
		{
			if (entry.getValue().size() == EXPECTED_PACK_SIZE && entry.getKey() > latestTime)
			{
				latestTime = entry.getKey();
				latest = List.copyOf(entry.getValue());
			}
		}
		return latest;
	}

	static String parseLocalPullMessage(String message)
	{
		String plain = message == null ? "" : Text.removeTags(message).replace('\u00a0', ' ').trim();
		if (!plain.startsWith(LOCAL_PULL_PREFIX) || !plain.endsWith(LOCAL_PULL_SUFFIX))
		{
			return null;
		}
		String cardName = plain.substring(LOCAL_PULL_PREFIX.length(),
			plain.length() - LOCAL_PULL_SUFFIX.length()).trim();
		if (cardName.toLowerCase(Locale.ROOT).startsWith("duplicate "))
		{
			cardName = cardName.substring("duplicate ".length()).trim();
		}
		if (cardName.toLowerCase(Locale.ROOT).endsWith(" (foil)"))
		{
			cardName = cardName.substring(0, cardName.length() - " (foil)".length()).trim();
		}
		return cardName.isEmpty() ? null : cardName;
	}

	private synchronized boolean consumeRecentChatPack(List<String> pack)
	{
		long now = System.currentTimeMillis();
		pruneRecentChatPacks(now);
		String signature = packSignature(pack);
		for (int i = 0; i < recentChatPacks.size(); i++)
		{
			if (recentChatPacks.get(i).signature.equals(signature))
			{
				recentChatPacks.remove(i);
				return true;
			}
		}
		return false;
	}

	private void pruneRecentChatPacks(long now)
	{
		recentChatPacks.removeIf(pack -> now - pack.detectedAt > CHAT_DEDUP_WINDOW_MILLIS);
	}

	private static String packSignature(List<String> pack)
	{
		List<String> normalized = new ArrayList<>();
		for (String name : pack)
		{
			normalized.add(name == null ? "" : name.trim().toLowerCase(Locale.ROOT));
		}
		normalized.sort(Comparator.naturalOrder());
		return String.join("\u0000", normalized);
	}

	static List<List<String>> detectPacks(Map<String, StoredCardInstance> previous,
		Map<String, StoredCardInstance> current)
	{
		Map<Long, List<StoredCardInstance>> byPullTime = new java.util.TreeMap<>();
		for (StoredCardInstance instance : current.values())
		{
			if (!previous.containsKey(instance.id) && instance.pulledAt > 0L)
			{
				byPullTime.computeIfAbsent(instance.pulledAt, ignored -> new ArrayList<>()).add(instance);
			}
		}
		List<List<String>> packs = new ArrayList<>();
		for (List<StoredCardInstance> group : byPullTime.values())
		{
			if (group.size() != EXPECTED_PACK_SIZE)
			{
				continue;
			}
			List<String> names = new ArrayList<>(EXPECTED_PACK_SIZE);
			for (StoredCardInstance instance : group)
			{
				names.add(instance.cardName);
			}
			packs.add(names);
		}
		return packs;
	}

	private static Map<String, StoredCardInstance> index(List<StoredCardInstance> instances)
	{
		Map<String, StoredCardInstance> result = new LinkedHashMap<>();
		for (StoredCardInstance instance : instances)
		{
			if (instance != null && instance.id != null && !instance.id.isEmpty())
			{
				result.put(instance.id, instance);
			}
		}
		return result;
	}

	static String decode(String stored)
	{
		if (stored == null || (!stored.startsWith(PREFIX_V3) && !stored.startsWith(PREFIX_V2)))
		{
			return "";
		}
		try
		{
			boolean legacyV2 = stored.startsWith(PREFIX_V2);
			String prefix = legacyV2 ? PREFIX_V2 : PREFIX_V3;
			byte[] compressed = Base64.getDecoder().decode(stored.substring(prefix.length()));
			if (legacyV2)
			{
				for (int i = 0; i < compressed.length; i++)
				{
					compressed[i] ^= XOR_SALT[i % XOR_SALT.length];
				}
			}
			try (GZIPInputStream gzip = new GZIPInputStream(new ByteArrayInputStream(compressed)))
			{
				return new String(gzip.readAllBytes(), StandardCharsets.UTF_8);
			}
		}
		catch (IllegalArgumentException | IOException ex)
		{
			return "";
		}
	}

	private static String sha256(String value)
	{
		try
		{
			byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
			StringBuilder hex = new StringBuilder(digest.length * 2);
			for (byte current : digest)
			{
				hex.append(String.format(Locale.ROOT, "%02x", current & 0xff));
			}
			return hex.toString();
		}
		catch (NoSuchAlgorithmException ex)
		{
			return null;
		}
	}

	static final class StoredState
	{
		long openedPacks;
		List<CardEntry> cardEntries;
		List<StoredCardInstance> cardInstances;

		List<StoredCardInstance> expandedInstances()
		{
			if (cardEntries == null || cardEntries.isEmpty())
			{
				return cardInstances == null ? Collections.emptyList() : cardInstances;
			}
			List<StoredCardInstance> result = new ArrayList<>();
			Map<String, Integer> occurrences = new HashMap<>();
			for (CardEntry entry : cardEntries)
			{
				if (entry == null || entry.cardName == null || entry.variants == null)
				{
					continue;
				}
				for (CardVariant variant : entry.variants)
				{
					if (variant == null)
					{
						continue;
					}
					int quantity = variant.quantity == null ? 1 : Math.max(0, variant.quantity);
					String pulledBy = variant.pulledBy == null ? "" : variant.pulledBy;
					long pulledAt = variant.pulledAt == null ? 0L : Math.max(0L, variant.pulledAt);
					boolean foil = Boolean.TRUE.equals(variant.foil);
					String signature = entry.cardName + "\u0000" + foil + "\u0000" + pulledBy + "\u0000" + pulledAt;
					for (int copy = 0; copy < quantity; copy++)
					{
						int occurrence = occurrences.merge(signature, 1, Integer::sum);
						StoredCardInstance instance = new StoredCardInstance();
						String stableId = variant.id == null ? "" : variant.id.trim();
						instance.id = stableId.isEmpty()
							? UUID.nameUUIDFromBytes((signature + "\u0000" + occurrence)
								.getBytes(StandardCharsets.UTF_8)).toString()
							: stableId;
						instance.cardName = entry.cardName.trim();
						instance.foil = foil;
						instance.pulledBy = pulledBy;
						instance.pulledAt = pulledAt;
						result.add(instance);
					}
				}
			}
			return result;
		}
	}

	private static final class RecentChatPack
	{
		private final String signature;
		private final long detectedAt;

		private RecentChatPack(String signature, long detectedAt)
		{
			this.signature = signature;
			this.detectedAt = detectedAt;
		}
	}

	static final class CardEntry
	{
		String cardName;
		List<CardVariant> variants;
	}

	static final class CardVariant
	{
		String id;
		Boolean foil;
		String pulledBy;
		Long pulledAt;
		Integer quantity;
	}

	static final class StoredCardInstance
	{
		String id;
		String cardName;
		boolean foil;
		String pulledBy;
		long pulledAt;
	}
}

