		readyUp.setToolTipText("Tell the party you are at the start line with the right loadout");
		readyUp.addActionListener(event ->
		{
			boolean ready = !raceService.snapshot().isLocalReady();
			clientThread.invokeLater(() -> raceService.setLocalReady(ready));
		});
		controls.add(readyUp);
		controls.add(Box.createVerticalStrut(5));
		howToPlay.setToolTipText("Show a walkthrough of a race round");
		howToPlay.addActionListener(event ->
		{
			showHelp = !showHelp;
			refresh();
		});
		controls.add(howToPlay);
		controls.add(Box.createVerticalStrut(5));

		JPanel roundControls = new JPanel(new GridLayout(1, 2, 5, 0));
		roundControls.setOpaque(false);
		endRound.setToolTipText("End the round you are hosting now and score everyone who has not finished as DNF");
		endRound.addActionListener(event -> clientThread.invokeLater(raceService::manualEndRound));
		cancelRound.setToolTipText("Abandon the round you are hosting. Nobody is scored and any points"
			+ " already awarded this round are handed back");
		cancelRound.addActionListener(event -> clientThread.invokeLater(raceService::cancelRound));
		roundControls.add(endRound);
		roundControls.add(cancelRound);
		controls.add(roundControls);
		controls.add(Box.createVerticalStrut(5));
		resetScores.setToolTipText("Clear the cumulative match score for the whole party");
		resetScores.addActionListener(event -> clientThread.invokeLater(raceService::resetScores));
		controls.add(resetScores);
		add(controls, BorderLayout.SOUTH);

		refreshTimer = new Timer(250, event -> refresh());
	}

	void start()
	{
		refreshTimer.start();
		refresh();
	}

	void stop()
	{
		refreshTimer.stop();
	}

	private void refresh()
	{
		RaceSnapshot snapshot = raceService.snapshot();
		boolean roundActive = snapshot.getState() == RaceSnapshot.State.COUNTDOWN
			|| snapshot.getState() == RaceSnapshot.State.RUNNING;
		integrationControls.setVisible(!integrationService.isImmediateDetectionReady());
		readyUp.setEnabled(!roundActive);
		readyUp.setText(snapshot.isLocalReady() ? "Ready ✓ — click to stand down" : "Ready up");
		readyUp.setBackground(snapshot.isLocalReady() ? READY_GREEN : READY_AMBER);
		howToPlay.setText(showHelp ? "Back to the race" : "How to play");
		endRound.setEnabled(roundActive);
		cancelRound.setEnabled(roundActive);
		resetScores.setEnabled(!snapshot.getScores().isEmpty());
		status.setText(statusText(snapshot));
		status.setForeground(statusColor(snapshot));
		roundLabel.setText(roundLabelText(snapshot));
		details.removeAll();

		if (showHelp)
		{
			details.add(helpPanel());
			details.revalidate();
			details.repaint();
			return;
		}

		if (snapshot.getState() == RaceSnapshot.State.IDLE && !snapshot.getParticipants().isEmpty())
		{
			int readyCount = snapshot.getReadyPlayers().size();
			int racerCount = snapshot.getParticipants().size();
			addSection("READY UP  " + readyCount + "/" + racerCount);
			addResultRow("Players ready", readyCount + " of " + racerCount,
				readyCount == racerCount ? GREEN : READY_AMBER);
		}

		if (!snapshot.getParticipants().isEmpty())
		{
			addSection("RACERS (" + snapshot.getParticipants().size() + ")");
			for (String participant : snapshot.getParticipants())
			{
				RacePlacement placement = placementFor(snapshot, participant);
				if (placement != null)
				{
					addResultRow(participant, RaceService.ordinal(placement.getPlace())
						+ "  +" + placement.getPoints(), GREEN);
				}
				else if (containsName(snapshot.getDnfPlayers(), participant))
				{
					addResultRow(participant, "DNF", RED);
				}
				else if (snapshot.getState() == RaceSnapshot.State.RUNNING)
				{
					addResultRow(participant, "RACING", MUTED);
				}
				else if (containsName(snapshot.getReadyPlayers(), participant))
				{
					addResultRow(participant, "READY", GREEN);
				}
				else
				{
					addResultRow(participant, "NOT READY", MUTED);
				}
			}
		}

		if (!snapshot.getCards().isEmpty())
		{
			addSection("ROUND OBJECTIVES");
			for (RaceCard card : snapshot.getCards())
			{
				addObjective(snapshot, card);
			}
		}
		else
		{
			JLabel waiting = new JLabel("<html><div style='text-align:center'>Open an OSRS TCG pack.<br>"
				+ "The race begins after card five is revealed.</div></html>", SwingConstants.CENTER);
			waiting.setForeground(MUTED);
			waiting.setAlignmentX(Component.CENTER_ALIGNMENT);
			waiting.setBorder(BorderFactory.createEmptyBorder(25, 5, 25, 5));
			details.add(waiting);
		}

		boolean queuedForMatch = isQueuedForMatch(snapshot);
		if (queuedForMatch && !snapshot.getScores().isEmpty())
		{
			addSection("MATCH SCORE");
			List<Map.Entry<String, Integer>> scores = new ArrayList<>(snapshot.getScores().entrySet());
			scores.sort(Map.Entry.<String, Integer>comparingByValue(Comparator.reverseOrder())
				.thenComparing(Map.Entry.comparingByKey(String.CASE_INSENSITIVE_ORDER)));
			for (Map.Entry<String, Integer> score : scores)
			{
				addResultRow(score.getKey(), score.getValue() + " pts", Color.WHITE);
			}
		}

		details.revalidate();
		details.repaint();
	}

