	private void addHelpSection(JPanel parent, String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(GOLD);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 11f));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(12, 2, 6, 0));
		parent.add(label);
	}

	private void addHelpText(JPanel parent, String html)
	{
		JLabel label = new JLabel("<html><div style='width:170px'>" + html + "</div></html>");
		label.setForeground(MUTED);
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
