	private void addObjective(RaceSnapshot snapshot, RaceCard card)
	{
		JPanel cardPanel = new JPanel();
		cardPanel.setLayout(new BoxLayout(cardPanel, BoxLayout.Y_AXIS));
		cardPanel.setAlignmentX(Component.LEFT_ALIGNMENT);
		cardPanel.setMaximumSize(new Dimension(Integer.MAX_VALUE, 140));
		cardPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		cardPanel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(new Color(68, 68, 68)),
			BorderFactory.createEmptyBorder(8, 9, 8, 9)));

		JLabel objective = new JLabel("<html><b>" + (card.getIndex() + 1) + ". "
			+ escape(card.getKind().getAction() + " " + card.getDisplayName()) + "</b></html>");
		objective.setForeground(GOLD);
		objective.setAlignmentX(Component.LEFT_ALIGNMENT);
		cardPanel.add(objective);

		boolean hasFinisher = false;
		for (RacePlacement placement : snapshot.getPlacements())
		{
			if (placement.getCardIndex() != card.getIndex())
			{
				continue;
			}
			hasFinisher = true;
			JLabel result = new JLabel(RaceService.ordinal(placement.getPlace()) + "  " + placement.getPlayerName()
				+ "   " + RaceService.formatDuration(placement.getElapsedMillis())
				+ "   (+" + placement.getPoints() + ")");
			result.setForeground(GREEN);
			result.setAlignmentX(Component.LEFT_ALIGNMENT);
			cardPanel.add(Box.createVerticalStrut(5));
			cardPanel.add(result);
		}
		if (!hasFinisher)
		{
			JLabel open = new JLabel("Open");
			open.setForeground(MUTED);
			open.setAlignmentX(Component.LEFT_ALIGNMENT);
			cardPanel.add(Box.createVerticalStrut(5));
			cardPanel.add(open);
		}
		details.add(cardPanel);
		details.add(Box.createVerticalStrut(6));
	}

	private void addSection(String text)
	{
		JLabel label = new JLabel(text);
		label.setForeground(MUTED);
		label.setFont(label.getFont().deriveFont(Font.BOLD, 10f));
		label.setAlignmentX(Component.LEFT_ALIGNMENT);
		label.setBorder(BorderFactory.createEmptyBorder(12, 2, 6, 0));
		details.add(label);
	}

	private void addResultRow(String left, String right, Color rightColor)
	{
		JPanel row = new JPanel(new BorderLayout());
		row.setOpaque(false);
		row.setAlignmentX(Component.LEFT_ALIGNMENT);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		JLabel leftLabel = new JLabel(left);
		leftLabel.setForeground(MUTED);
		JLabel rightLabel = new JLabel(right);
		rightLabel.setForeground(rightColor);
		row.add(leftLabel, BorderLayout.WEST);
		row.add(rightLabel, BorderLayout.EAST);
		details.add(row);
	}

	private String roundLabelText(RaceSnapshot snapshot)
	{
		if (!isQueuedForMatch(snapshot))
		{
			return "";
		}
		MatchState match = snapshot.getMatch();
		if (match.isComplete())
		{
			return match.getLeader().isEmpty()
				? "MATCH COMPLETE" : "MATCH COMPLETE — " + match.getLeader() + " WINS";
		}
		return match.label();
	}

	private String statusText(RaceSnapshot snapshot)
	{
		long now = System.currentTimeMillis();
		if (snapshot.getState() == RaceSnapshot.State.IDLE && now < setupStatusUntil)
		{
			return setupStatus;
		}
		switch (snapshot.getState())
		{
			case COUNTDOWN:
				return "STARTING IN " + Math.max(0L, (snapshot.getStartsAt() - now + 999L) / 1_000L);
			case RUNNING:
				return snapshot.getDnfDeadlineAt() > 0L
					? "DNF CUTOFF  " + RaceService.formatDuration(snapshot.getDnfDeadlineAt() - now)
					: "RACING  " + RaceService.formatDuration(now - snapshot.getStartsAt());
			case FINISHED:
				return "ROUND COMPLETE";
			default:
				if (snapshot.isSyncLost())
				{
					return "SYNC LOST — REQUESTING HOST STATE";
				}
				if (isQueuedForMatch(snapshot) && snapshot.getMatch().isComplete())
				{
					return "MATCH OVER — RESET SCORES FOR A NEW ONE";
				}
				if (config.requireEveryoneReady() && !snapshot.getParticipants().isEmpty())
				{
					int ready = snapshot.getReadyPlayers().size();
					int racers = snapshot.getParticipants().size();
					if (ready < racers)
					{
						return snapshot.isPackArmed()
							? "PACK ARMED — WAITING ON " + (racers - ready)
							: "READY CHECK  " + ready + "/" + racers;
					}
					return "ALL READY — OPEN A PACK";
				}
				if (!config.showOverlay())
				{
					return "ON-SCREEN DISPLAY OFF — ENABLE IN SETTINGS";
				}
				if (!integrationService.isImmediateDetectionReady())
				{
					return "ONE-TIME SETUP REQUIRED";
				}

				return "WAITING FOR FIVE REVEALS";
		}
	}

	private static boolean isQueuedForMatch(RaceSnapshot snapshot)
	{
		return snapshot.getState() != RaceSnapshot.State.IDLE
			|| snapshot.isLocalReady() || snapshot.isPackArmed();
	}

	private static Color statusColor(RaceSnapshot snapshot)
	{
		switch (snapshot.getState())
		{
			case COUNTDOWN: return GOLD;
			case RUNNING: return snapshot.getDnfDeadlineAt() > 0L ? RED : GREEN;
			case FINISHED: return GREEN;
			default: return Color.WHITE;
		}
	}

	private static JButton actionButton(String text, Color background)
	{
		JButton button = new JButton(text);
		button.setFocusPainted(false);
		button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		button.setBackground(background);
		button.setForeground(Color.WHITE);
		button.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(background.brighter()),
			BorderFactory.createEmptyBorder(7, 6, 7, 6)));
		return button;
	}

	private static RacePlacement placementFor(RaceSnapshot snapshot, String playerName)
	{
		for (RacePlacement placement : snapshot.getPlacements())
		{
			if (placement.getPlayerName().equalsIgnoreCase(playerName))
			{
				return placement;
			}
		}
		return null;
	}

	private static boolean containsName(List<String> names, String playerName)
	{
		for (String name : names)
		{
			if (name.equalsIgnoreCase(playerName))
			{
				return true;
			}
		}
		return false;
	}

	private static String escape(String value)
	{
		return value == null ? "" : value.replace("&", "&amp;")
			.replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.tcgrace;

import com.google.inject.Provides;
import com.tcgrace.party.RaceClaimMessage;
import com.tcgrace.party.RaceCountdownHoldMessage;
import com.tcgrace.party.RacePlacementMessage;
import com.tcgrace.party.RaceReadyMessage;
import com.tcgrace.party.RaceRoundCancelMessage;
import com.tcgrace.party.RaceRoundEndMessage;
import com.tcgrace.party.RaceRoundStartMessage;
import com.tcgrace.party.RaceScoreResetMessage;
import com.tcgrace.party.RaceStateRequestMessage;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.Client;
import net.runelite.api.events.ActorDeath;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "TCGG",
	description = "Race friends to complete one of five objectives drawn from an OSRS TCG pack",
	tags = {"tcg", "race", "party", "challenge"}
)
public class TcgRacePlugin extends Plugin
{
	@Inject private RaceService raceService;
	@Inject private Client client;
	@Inject private TcgPackDetector packDetector;
	@Inject private RaceOverlay overlay;
	@Inject private OverlayManager overlayManager;
	@Inject private TcgRacePanel panel;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ConfigManager configManager;
	@Inject private WSClient wsClient;
	@Inject private ClientThread clientThread;

	private NavigationButton navigationButton;

	@Override
	protected void startUp()
	{
		registerPartyMessages();
		raceService.start();
		packDetector.useAccount(client.getAccountHash(), configManager.getRSProfileKey());
		packDetector.start(raceService::onDetectedPack);
		overlayManager.add(overlay);
		navigationButton = NavigationButton.builder()
			.tooltip("TCGG")
			.icon(createIcon())
			.priority(6)
			.panel(panel)
			.build();
		SwingUtilities.invokeLater(() ->
		{
			panel.start();
			clientToolbar.addNavigation(navigationButton);
		});
		log.info("TCGG started");
	}

	@Override
	protected void shutDown()
	{
		packDetector.stop();
		raceService.stop();
		overlayManager.remove(overlay);
		unregisterPartyMessages();
		NavigationButton current = navigationButton;
		navigationButton = null;
		SwingUtilities.invokeLater(() ->
		{
			panel.stop();
			if (current != null)
			{
				clientToolbar.removeNavigation(current);
			}
		});
		log.info("TCGG stopped");
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		raceService.onGameTick();
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		packDetector.onChatMessage(event);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			packDetector.useAccount(client.getAccountHash(), configManager.getRSProfileKey());
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		packDetector.useAccount(client.getAccountHash(), configManager.getRSProfileKey());
		raceService.profileChanged();
	}

	@Subscribe
	public void onPartyChanged(PartyChanged event)
	{
		raceService.requestPartyState();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		raceService.onItemContainerChanged(event);
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		raceService.onMenuOptionClicked(event);
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		raceService.onHitsplatApplied(event);
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		raceService.onActorDeath(event);
	}

	@Subscribe
	public void onRaceRoundStartMessage(RaceRoundStartMessage message)
	{
		clientThread.invokeLater(() -> raceService.onRoundStart(message));
	}

	@Subscribe
	public void onRaceClaimMessage(RaceClaimMessage message)
	{
		clientThread.invokeLater(() -> raceService.onClaim(message));
	}

	@Subscribe
	public void onRaceCountdownHoldMessage(RaceCountdownHoldMessage message)
	{
		clientThread.invokeLater(() -> raceService.onCountdownHold(message));
	}

	@Subscribe
	public void onRacePlacementMessage(RacePlacementMessage message)
	{
		clientThread.invokeLater(() -> raceService.onPlacement(message));
	}

	@Subscribe
	public void onRaceRoundEndMessage(RaceRoundEndMessage message)
	{
		clientThread.invokeLater(() -> raceService.onRoundEnd(message));
	}

	@Subscribe
	public void onRaceRoundCancelMessage(RaceRoundCancelMessage message)
	{
		clientThread.invokeLater(() -> raceService.onRoundCancel(message));
	}

	@Subscribe
	public void onRaceReadyMessage(RaceReadyMessage message)
	{
		clientThread.invokeLater(() -> raceService.onReady(message));
	}

	@Subscribe
	public void onRaceScoreResetMessage(RaceScoreResetMessage message)
	{
		clientThread.invokeLater(() -> raceService.onScoreReset(message));
	}

	@Subscribe
	public void onRaceStateRequestMessage(RaceStateRequestMessage message)
	{
		clientThread.invokeLater(() -> raceService.onStateRequest(message));
	}

	@Provides
	TcgRaceConfig provideConfig(ConfigManager manager)
	{
		return manager.getConfig(TcgRaceConfig.class);
	}

	private void registerPartyMessages()
	{
		wsClient.registerMessage(RaceRoundStartMessage.class);
		wsClient.registerMessage(RaceClaimMessage.class);
		wsClient.registerMessage(RaceCountdownHoldMessage.class);
		wsClient.registerMessage(RacePlacementMessage.class);
		wsClient.registerMessage(RaceRoundEndMessage.class);
		wsClient.registerMessage(RaceRoundCancelMessage.class);
		wsClient.registerMessage(RaceReadyMessage.class);
		wsClient.registerMessage(RaceScoreResetMessage.class);
		wsClient.registerMessage(RaceStateRequestMessage.class);
	}

	private void unregisterPartyMessages()
	{
		wsClient.unregisterMessage(RaceRoundStartMessage.class);
		wsClient.unregisterMessage(RaceClaimMessage.class);
		wsClient.unregisterMessage(RaceCountdownHoldMessage.class);
		wsClient.unregisterMessage(RacePlacementMessage.class);
		wsClient.unregisterMessage(RaceRoundEndMessage.class);
		wsClient.unregisterMessage(RaceRoundCancelMessage.class);
		wsClient.unregisterMessage(RaceReadyMessage.class);
		wsClient.unregisterMessage(RaceScoreResetMessage.class);
		wsClient.unregisterMessage(RaceStateRequestMessage.class);
	}

	private static BufferedImage createIcon()
	{
		BufferedImage image = new BufferedImage(20, 20, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			graphics.setStroke(new BasicStroke(1.5f));
			for (int i = 0; i < 5; i++)
			{
				graphics.setColor(i == 0 ? new Color(255, 196, 64) : new Color(218, 218, 218));
				graphics.drawRoundRect(1 + i * 4, 3 + Math.abs(2 - i), 6, 12, 2, 2);
			}
		}
		finally
		{
			graphics.dispose();
		}
		return image;
	}
}

package com.tcgrace.model;

import lombok.Value;

/**
 * Where the party is in a multi-round match.
 *
 * <p>The round host owns these numbers and sends them with every round, so a guest that joins
 * part way through still shows the correct round of the correct match.</p>
 */
@Value
public class MatchState
{
	/** 1-based number of the current or most recent round, or 0 before a match starts. */
	int round;
	/** Rounds this match is scheduled to run, or 0 for an open-ended match. */
	int totalRounds;
	/** Rounds completed so far. A cancelled round does not count. */
	int roundsPlayed;
	/** True once {@link #roundsPlayed} has reached a non-zero {@link #totalRounds}. */
	boolean complete;
	/** Highest scoring racer, or an empty string when nobody has scored yet. */
	String leader;
	int leaderPoints;

	public static MatchState idle()
	{
		return new MatchState(0, 0, 0, false, "", 0);
	}

	/** "ROUND 2 / 5", or "ROUND 2" when the match is open-ended. */
	public String label()
	{
		if (round <= 0)
		{
			return "";
		}
		return totalRounds > 0 ? "ROUND " + round + " / " + totalRounds : "ROUND " + round;
	}
}

