@Getter
public final class RaceSnapshot
{
	public enum State { IDLE, COUNTDOWN, RUNNING, FINISHED }

	private final String roundId;
	private final State state;
	private final long startsAt;
	private final long endsAt;
	private final long dnfDeadlineAt;
	private final List<RaceCard> cards;
	private final List<RacePlacement> placements;
	private final List<String> participants;
	private final List<String> dnfPlayers;
	private final Map<String, Integer> scores;
	private final boolean localInvalid;
	private final String localInvalidReason;
	/** A round is running that this client received but could not resolve into objectives. */
	private final boolean syncLost;
	/** Racers who have pressed Ready up for the next round. */
	private final List<String> readyPlayers;
	private final boolean localReady;
	private final MatchState match;
	/** A pack is opened and waiting for the last racer to ready up. */
	private final boolean packArmed;

	public RaceSnapshot(String roundId, State state, long startsAt, long endsAt, long dnfDeadlineAt,
		List<RaceCard> cards, List<RacePlacement> placements, List<String> participants,
		List<String> dnfPlayers, Map<String, Integer> scores, boolean localInvalid, String localInvalidReason,
		boolean syncLost, List<String> readyPlayers, boolean localReady, MatchState match, boolean packArmed)
	{
		this.roundId = roundId == null ? "" : roundId;
		this.state = state == null ? State.IDLE : state;
		this.startsAt = startsAt;
		this.endsAt = endsAt;
		this.dnfDeadlineAt = dnfDeadlineAt;
		this.cards = Collections.unmodifiableList(new ArrayList<>(cards == null ? Collections.emptyList() : cards));
		this.placements = Collections.unmodifiableList(new ArrayList<>(placements == null ? Collections.emptyList() : placements));
		this.participants = Collections.unmodifiableList(new ArrayList<>(participants == null ? Collections.emptyList() : participants));
		this.dnfPlayers = Collections.unmodifiableList(new ArrayList<>(dnfPlayers == null ? Collections.emptyList() : dnfPlayers));
		this.scores = Collections.unmodifiableMap(new LinkedHashMap<>(scores == null ? Collections.emptyMap() : scores));
		this.localInvalid = localInvalid;
		this.localInvalidReason = localInvalidReason == null ? "" : localInvalidReason;
		this.syncLost = syncLost;
		this.readyPlayers = Collections.unmodifiableList(
			new ArrayList<>(readyPlayers == null ? Collections.emptyList() : readyPlayers));
		this.localReady = localReady;
		this.match = match == null ? MatchState.idle() : match;
		this.packArmed = packArmed;
	}

	public static RaceSnapshot idle(Map<String, Integer> scores)
	{
		return new RaceSnapshot("", State.IDLE, 0L, 0L, 0L, Collections.emptyList(),
			Collections.emptyList(), Collections.emptyList(), Collections.emptyList(), scores, false, "", false, Collections.emptyList(), false, MatchState.idle(), false);
	}
}

