public class RaceServiceTest
{
	@Test
	public void formatsRaceTimesToTenths()
	{
		assertEquals("00:00.0", RaceService.formatDuration(0L));
		assertEquals("02:03.4", RaceService.formatDuration(123499L));
		assertEquals("1:02:03.4", RaceService.formatDuration(3723499L));
	}

	@Test
	public void usesDnfGraceDeadlineAfterFirstPlace()
	{
		assertEquals(60_000L, RaceService.effectiveDeadline(60_000L, 0L));
		assertEquals(20_000L, RaceService.effectiveDeadline(60_000L, 20_000L));
		assertEquals(60_000L, RaceService.effectiveDeadline(60_000L, 90_000L));
	}

	@Test
	public void marksOnlyPlayersWithoutAPlacementAsDnf()
	{
		RacePlacement first = new RacePlacement("Alice", 1, 5, 10_000L, 2, "Killed Goblin");
		RacePlacement secondOnSameCard = new RacePlacement("Bob", 2, 4, 12_000L, 2, "Killed Goblin");

		assertEquals(Collections.singletonList("Cara"), RaceService.unfinishedParticipants(
			Arrays.asList("Alice", "Bob", "Cara", "alice"),
			Arrays.asList(first, secondOnSameCard)));
	}

	@Test
	public void spellsPlaceOrdinalsCorrectlyPastTenth()
	{
		assertEquals("1st", RaceService.ordinal(1));
		assertEquals("2nd", RaceService.ordinal(2));
		assertEquals("3rd", RaceService.ordinal(3));
		assertEquals("4th", RaceService.ordinal(4));
		assertEquals("11th", RaceService.ordinal(11));
		assertEquals("12th", RaceService.ordinal(12));
		assertEquals("13th", RaceService.ordinal(13));
		assertEquals("21st", RaceService.ordinal(21));
		assertEquals("22nd", RaceService.ordinal(22));
		assertEquals("23rd", RaceService.ordinal(23));
	}

	@Test
	public void locksGameActionsButLeavesCameraAndPluginUiAvailable()
	{
		assertTrue(RaceService.isCountdownBlockedAction(MenuAction.WALK));
		assertTrue(RaceService.isCountdownBlockedAction(MenuAction.NPC_FIRST_OPTION));
		assertFalse(RaceService.isCountdownBlockedAction(MenuAction.SET_HEADING));
		assertFalse(RaceService.isCountdownBlockedAction(MenuAction.EXAMINE_NPC));
		assertFalse(RaceService.isCountdownBlockedAction(MenuAction.RUNELITE));
	}
}

