/**
 * In-memory stand-in for a RuneLite Party of TCGG clients.
 *
 * <p>Every simulated client owns a real {@link RaceService} wired to mocked RuneLite services. Party
 * traffic is queued on a shared bus and delivered on {@link #tick()} to the same handlers that
 * {@link TcgRacePlugin} subscribes, so host and guest interplay is exercised end to end. Time is
 * driven by the simulation instead of the wall clock, so multi-minute DNF windows run instantly.
 */
final class RaceSimulation
{
	/** Catalog entries a simulated pack can draw from, keyed by the printed card name. */
	private static final Map<String, RaceCard> CATALOG = new LinkedHashMap<>();

	static
	{
		catalogItem("Shark", "Shark", 385);
		catalogItem("Dragon Bones", "Dragon bones", 536);
		catalogItem("Rune Scimitar", "Rune scimitar", 1333);
		catalogMonster("Goblin", "Goblin", 3029, 3030);
		catalogMonster("Hill Giant", "Hill Giant", 2098);
		catalogNpc("Bob", "Bob", 519);
		catalogNpc("Hans", "Hans", 3105);
	}

	/** A default five-card pack: three items, one monster, one interaction NPC. */
	static final List<String> DEFAULT_PACK =
		Arrays.asList("Shark", "Dragon Bones", "Rune Scimitar", "Goblin", "Bob");

	/** The two items the shipped starter-loadout rule expects a racer to begin with. */
	static final int DRAMEN_STAFF = 772;
	static final int ARDOUGNE_CLOAK_4 = 13124;

	/**
	 * Both stamina variations, every dose. The shipped rules allow all of them and require none.
	 * Regular potions come from Herblore; the two-dose mixes come from Barbarian Herblore.
	 */
	static final int[] STAMINA_POTION_DOSES = {12625, 12627, 12629, 12631};
	static final int[] STAMINA_MIX_DOSES = {12635, 12637};

	/** The legal starting tile for the shipped Kandarin Monastery rule. */
	static final WorldPoint MONASTERY = new WorldPoint(2606, 3219, 0);

	private static final Map<Integer, String> ITEM_NAMES = new LinkedHashMap<>();

	static
	{
		ITEM_NAMES.put(DRAMEN_STAFF, "Dramen staff");
		ITEM_NAMES.put(ARDOUGNE_CLOAK_4, "Ardougne cloak 4");
		ITEM_NAMES.put(385, "Shark");
		ITEM_NAMES.put(536, "Dragon bones");
		ITEM_NAMES.put(1333, "Rune scimitar");
		ITEM_NAMES.put(2440, "Super strength(4)");
		for (int dose = 0; dose < STAMINA_POTION_DOSES.length; dose++)
		{
			ITEM_NAMES.put(STAMINA_POTION_DOSES[dose], "Stamina potion(" + (4 - dose) + ")");
		}
		for (int dose = 0; dose < STAMINA_MIX_DOSES.length; dose++)
		{
			ITEM_NAMES.put(STAMINA_MIX_DOSES[dose], "Stamina mix(" + (2 - dose) + ")");
		}
	}

	private final Deque<PartyMessage> bus = new ArrayDeque<>();
	private final List<SimClient> clients = new ArrayList<>();
	private long time = 1_700_000_000_000L;
	private int tickCount = 100;

	long now()
	{
		return time;
	}

	List<SimClient> clients()
	{
		return clients;
	}

	SimClient client(String name)
	{
		for (SimClient candidate : clients)
		{
			if (candidate.name.equalsIgnoreCase(name))
			{
				return candidate;
			}
		}
		throw new IllegalArgumentException("No simulated client named " + name);
	}

	/** Adds a party member and returns its client. The first client added is the natural host. */
	SimClient join(String playerName)
	{
		SimClient added = new SimClient(playerName, 100L + clients.size());
		clients.add(added);
		return added;
	}

	/** Advances one game tick: delivers queued party traffic, then runs every client tick handler. */
	void tick()
	{
		drainBus();
		tickCount++;
		for (SimClient simClient : new ArrayList<>(clients))
		{
			simClient.service.onGameTick();
		}
		drainBus();
	}

	/** Advances the simulated clock by {@code millis}, ticking once per 600ms game tick. */
	void advance(long millis)
	{
		long remaining = millis;
		while (remaining > 0L)
		{
			long step = Math.min(600L, remaining);
			time += step;
			remaining -= step;
			tick();
		}
	}

	/** Advances past the countdown so every client is RUNNING with a captured item baseline. */
	void startTimer(int countdownSeconds)
	{
		advance(countdownSeconds * 1_000L + 600L);
	}

	void drainBus()
	{
		int guard = 0;
		while (!bus.isEmpty())
		{
			if (++guard > 10_000)
			{
				throw new IllegalStateException("Party message bus did not settle");
			}
			PartyMessage message = bus.poll();
			for (SimClient target : new ArrayList<>(clients))
			{
				target.dispatch(message);
			}
		}
	}

	/** One simulated RuneLite client: a real RaceService plus the mocked game state it observes. */
	final class SimClient
	{
		final String name;
		final long memberId;
		final SimConfig config = new SimConfig();
		final RaceService service;
		final List<String> chat = new ArrayList<>();
		final Map<Integer, Integer> inventory = new HashMap<>();

		private final Client gameClient = mock(Client.class);
		private final Player localPlayer = mock(Player.class);
		private final PartyService partyService = mock(PartyService.class);
		private final ItemContainer inventoryContainer = mock(ItemContainer.class);
		private final ItemContainer equipmentContainer = mock(ItemContainer.class);
		private final PartyMember localMember;

		private WorldPoint location = MONASTERY;
		private boolean inParty = true;
		private boolean catalogReady = true;

		private SimClient(String memberName, long id)
		{
			this.name = memberName;
			this.memberId = id;
			localMember = new PartyMember(id);
			localMember.setDisplayName(memberName);
			localMember.setLoggedIn(true);
			// Most scenarios are not about the match schedule, so matches run open ended by default.
			config.totalRounds = 0;
			// Most scenarios are not about the ready gate, so it is off unless a test turns it on.
			config.requireEveryoneReady = false;
			// Start every racer legal under the shipped rules: monastery tile, staff and cloak carried.
			inventory.put(DRAMEN_STAFF, 1);
			inventory.put(ARDOUGNE_CLOAK_4, 1);

			when(localPlayer.getName()).thenReturn(memberName);
			when(localPlayer.getWorldLocation()).thenAnswer(invocation -> location);
			when(gameClient.getLocalPlayer()).thenReturn(localPlayer);
			when(gameClient.getTickCount()).thenAnswer(invocation -> tickCount);
			doAnswer(invocation ->
			{
				chat.add(invocation.getArgument(2, String.class));
				return null;
			}).when(gameClient).addChatMessage(any(), anyString(), anyString(), any());

			when(inventoryContainer.getItems()).thenAnswer(invocation -> itemArray());
			when(equipmentContainer.getItems()).thenAnswer(invocation -> new Item[0]);
			when(gameClient.getItemContainer(anyInt())).thenAnswer(invocation ->
				(int) invocation.getArgument(0) == InventoryID.WORN ? equipmentContainer : inventoryContainer);

			when(partyService.isInParty()).thenAnswer(invocation -> inParty);
			when(partyService.getLocalMember()).thenAnswer(invocation -> inParty ? localMember : null);
			when(partyService.getMembers()).thenAnswer(invocation -> partyMembers());
			when(partyService.getMemberById(anyLong())).thenAnswer(invocation -> memberById(invocation.getArgument(0)));
			doAnswer(invocation ->
			{
				PartyMessage sent = invocation.getArgument(0);
				if (sent instanceof PartyMemberMessage)
				{
					((PartyMemberMessage) sent).setMemberId(id);
				}
				bus.add(sent);
				return null;
			}).when(partyService).send(any());

			TcgCatalogService catalogService = mock(TcgCatalogService.class);
			when(catalogService.resolvePack(any())).thenAnswer(invocation ->
				catalogReady ? resolve(invocation.getArgument(0)) : unresolved(invocation.getArgument(0)));

			ItemManager itemManager = mock(ItemManager.class);
			when(itemManager.getItemComposition(anyInt())).thenAnswer(invocation ->
			{
				int itemId = invocation.getArgument(0);
				ItemComposition composition = mock(ItemComposition.class);
				when(composition.getName()).thenReturn(ITEM_NAMES.getOrDefault(itemId, "Simulated item " + itemId));
				return composition;
			});
			ConfigManager configManager = mock(ConfigManager.class);

			service = new RaceService(gameClient, config, partyService, catalogService,
				itemManager, configManager, new Gson());
			service.useClock(RaceSimulation.this::now);
			service.start();
		}

		RaceSnapshot snapshot()
		{
			return service.snapshot();
		}

		void leaveParty()
		{
			inParty = false;
		}

		/** Presses Ready up (or stands down) in this client's sidebar. */
		void ready(boolean ready)
		{
			service.setLocalReady(ready);
			drainBus();
		}

		/** Simulates this client's live OSRS TCG catalog being unavailable or still loading. */
		void useCatalog(boolean ready)
		{
			catalogReady = ready;
		}

		/** Opens a pack on this client, which makes it the host of the resulting round. */
		void openPack(List<String> cardNames)
		{
			service.onDetectedPack(new ArrayList<>(cardNames));
			drainBus();
		}

		void moveTo(WorldPoint destination)
		{
			location = destination;
		}

		/** Adds an item and fires the inventory event RuneLite would raise. */
		void obtain(int itemId, int quantity)
		{
			inventory.merge(itemId, quantity, Integer::sum);
			service.onItemContainerChanged(new ItemContainerChanged(InventoryID.INV, inventoryContainer));
			drainBus();
		}

		/** Left-clicks a menu entry on an NPC, e.g. "Talk-to" for an interaction objective. */
		void clickNpc(String option, int npcId)
		{
			NPC npc = npc(npcId, npcId);
			MenuEntry entry = mock(MenuEntry.class);
			when(entry.getOption()).thenReturn(option);
			when(entry.getType()).thenReturn(MenuAction.NPC_FIRST_OPTION);
			when(entry.getNpc()).thenReturn(npc);
			service.onMenuOptionClicked(new MenuOptionClicked(entry));
			drainBus();
		}

		/** Clicks a menu option belonging to a game interface, e.g. a Grand Exchange offer. */
		MenuOptionClicked clickWidget(String option, MenuAction action, int interfaceGroup)
		{
			MenuEntry entry = mock(MenuEntry.class);
			when(entry.getOption()).thenReturn(option);
			when(entry.getType()).thenReturn(action);
			when(entry.getParam1()).thenReturn(interfaceGroup << 16);
			MenuOptionClicked event = new MenuOptionClicked(entry);
			service.onMenuOptionClicked(event);
			drainBus();
			return event;
		}

		/** Clicks a plain menu option with no NPC attached, e.g. a bank withdrawal. */
		MenuOptionClicked clickOption(String option, MenuAction action)
		{
			MenuEntry entry = mock(MenuEntry.class);
			when(entry.getOption()).thenReturn(option);
			when(entry.getType()).thenReturn(action);
			MenuOptionClicked event = new MenuOptionClicked(entry);
			service.onMenuOptionClicked(event);
			drainBus();
			return event;
		}

		/** Lands a hit on a monster, which is what marks it as engaged by this player. */
		void hit(int npcId, int npcIndex)
		{
			hit(npcId, npcIndex, true);
		}

		/** Lands a hit that another player dealt, which must not count as this player engaging. */
		void watchSomebodyElseHit(int npcId, int npcIndex)
		{
			hit(npcId, npcIndex, false);
		}

		private void hit(int npcId, int npcIndex, boolean mine)
		{
			Hitsplat hitsplat = mock(Hitsplat.class);
			when(hitsplat.isMine()).thenReturn(mine);
			HitsplatApplied event = new HitsplatApplied();
			event.setActor(npc(npcId, npcIndex));
			event.setHitsplat(hitsplat);
			service.onHitsplatApplied(event);
			drainBus();
		}

		void kill(int npcId, int npcIndex)
		{
			service.onActorDeath(new ActorDeath(npc(npcId, npcIndex)));
			drainBus();
		}

		private NPC npc(int npcId, int npcIndex)
		{
			NPC npc = mock(NPC.class);
			when(npc.getId()).thenReturn(npcId);
			when(npc.getIndex()).thenReturn(npcIndex);
			return npc;
		}

		private Item[] itemArray()
		{
			List<Item> items = new ArrayList<>();
			for (Map.Entry<Integer, Integer> entry : inventory.entrySet())
			{
				items.add(new Item(entry.getKey(), entry.getValue()));
			}
			return items.toArray(new Item[0]);
		}

		private List<PartyMember> partyMembers()
		{
			List<PartyMember> members = new ArrayList<>();
			if (!inParty)
			{
				return members;
			}
			for (SimClient other : clients)
			{
				members.add(other.localMember);
			}
			return members;
		}

		private PartyMember memberById(long id)
		{
			for (SimClient other : clients)
			{
				if (other.memberId == id)
				{
					return other.localMember;
				}
			}
			return null;
		}

		private void dispatch(PartyMessage message)
		{
			if (message instanceof RaceRoundStartMessage)
			{
				service.onRoundStart((RaceRoundStartMessage) message);
			}
			else if (message instanceof RaceClaimMessage)
			{
				service.onClaim((RaceClaimMessage) message);
			}
			else if (message instanceof RaceCountdownHoldMessage)
			{
				service.onCountdownHold((RaceCountdownHoldMessage) message);
			}
			else if (message instanceof RacePlacementMessage)
			{
				service.onPlacement((RacePlacementMessage) message);
			}
			else if (message instanceof RaceRoundEndMessage)
			{
				service.onRoundEnd((RaceRoundEndMessage) message);
			}
			else if (message instanceof RaceRoundCancelMessage)
			{
				service.onRoundCancel((RaceRoundCancelMessage) message);
			}
			else if (message instanceof RaceReadyMessage)
			{
				service.onReady((RaceReadyMessage) message);
			}
			else if (message instanceof RaceScoreResetMessage)
			{
				service.onScoreReset((RaceScoreResetMessage) message);
			}
			else if (message instanceof RaceStateRequestMessage)
			{
				service.onStateRequest((RaceStateRequestMessage) message);
			}
		}
	}

	private static List<RaceCard> resolve(List<String> names)
	{
		List<RaceCard> resolved = new ArrayList<>();
		if (names == null)
		{
			return resolved;
		}
		for (int index = 0; index < names.size(); index++)
		{
			String pulled = names.get(index) == null ? "" : names.get(index).trim();
			RaceCard template = CATALOG.get(normalize(pulled));
			resolved.add(template == null
				? new RaceCard(index, pulled, pulled, ObjectiveKind.UNKNOWN, Collections.emptyList())
				: new RaceCard(index, template.getCardName(), template.getDisplayName(),
					template.getKind(), template.getTargetIds()));
		}
		return resolved;
	}

	/** Every card resolves to an unsupported objective, as it does before the live catalog loads. */
	private static List<RaceCard> unresolved(List<String> names)
	{
		List<RaceCard> result = new ArrayList<>();
		if (names != null)
		{
			for (int index = 0; index < names.size(); index++)
			{
				String pulled = names.get(index) == null ? "" : names.get(index).trim();
				result.add(new RaceCard(index, pulled, pulled, ObjectiveKind.UNKNOWN, Collections.emptyList()));
			}
		}
		return result;
	}

	private static void catalogItem(String cardName, String displayName, Integer... ids)
	{
		CATALOG.put(normalize(cardName), new RaceCard(0, cardName, displayName, ObjectiveKind.ITEM, Arrays.asList(ids)));
	}

	private static void catalogMonster(String cardName, String displayName, Integer... ids)
	{
		CATALOG.put(normalize(cardName), new RaceCard(0, cardName, displayName, ObjectiveKind.MONSTER, Arrays.asList(ids)));
	}

	private static void catalogNpc(String cardName, String displayName, Integer... ids)
	{
		CATALOG.put(normalize(cardName), new RaceCard(0, cardName, displayName, ObjectiveKind.NPC, Arrays.asList(ids)));
	}

	static int targetId(String cardName)
	{
		return CATALOG.get(normalize(cardName)).getTargetIds().get(0);
	}

	private static String normalize(String value)
	{
		return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
	}
}

