	@Test
	public void awardsFiveDownToOnePointAcrossEveryFinishingPlace()
	{
		RaceSimulation sim = new RaceSimulation();
		SimClient host = sim.join("Host");
		SimClient second = sim.join("Runner Two");
		SimClient third = sim.join("Runner Three");
		SimClient fourth = sim.join("Runner Four");
		SimClient fifth = sim.join("Runner Five");

		host.openPack(RaceSimulation.DEFAULT_PACK);
		sim.startTimer(5);

		for (SimClient finisher : Arrays.asList(host, second, third, fourth, fifth))
		{
			sim.advance(1_200L);
			finisher.obtain(SHARK, 1);
		}

		RaceSnapshot hosted = host.snapshot();
		assertEquals(Arrays.asList("Host", "Runner Two", "Runner Three", "Runner Four", "Runner Five"),
			placementNames(hosted));
		assertEquals(Arrays.asList(1, 2, 3, 4, 5), places(hosted));
		assertEquals(Arrays.asList(5, 4, 3, 2, 1), points(hosted));
		assertEquals(Integer.valueOf(5), hosted.getScores().get("Host"));
		assertEquals(Integer.valueOf(1), hosted.getScores().get("Runner Five"));

		// Every guest ends the round holding the same ordered result table as the host.
		for (SimClient guest : Arrays.asList(second, third, fourth, fifth))
		{
			RaceSnapshot mirrored = guest.snapshot();
			assertEquals(placementNames(hosted), placementNames(mirrored));
			assertEquals(points(hosted), points(mirrored));
			assertEquals(RaceSnapshot.State.FINISHED, mirrored.getState());
		}
		assertEquals(RaceSnapshot.State.FINISHED, hosted.getState());
		assertTrue(hosted.getDnfPlayers().isEmpty());
	}

