		sim.advance(299_000L);
		assertEquals(RaceSnapshot.State.RUNNING, host.snapshot().getState());
		second.obtain(SHARK, 1);
		assertEquals(2, host.snapshot().getPlacements().size());

		sim.advance(2_000L);

		RaceSnapshot hosted = host.snapshot();
		assertEquals(RaceSnapshot.State.FINISHED, hosted.getState());
		assertEquals(Collections.singletonList("Runner Three"), hosted.getDnfPlayers());
		assertTrue(host.chat.contains(RaceService.CHAT_PREFIX + "Round over: DNF grace period expired."));
		assertEquals(Collections.singletonList("Runner Three"), straggler.snapshot().getDnfPlayers());
		assertEquals(RaceSnapshot.State.FINISHED, straggler.snapshot().getState());

		// The straggler can no longer claim an objective after the cutoff.
		straggler.obtain(SHARK, 1);
		assertEquals(2, host.snapshot().getPlacements().size());
