		assertEquals(RaceSnapshot.State.IDLE, lost.getState());
		assertTrue(lost.isSyncLost());
		assertTrue(guest.chat.contains(RaceService.CHAT_PREFIX + "A race started, but this client cannot resolve its cards yet."
			+ " Open the OSRS TCG sidebar to refresh the live catalog."));

		// The warning is not repeated while the same round keeps being rebroadcast.
		sim.advance(12_000L);
		assertTrue(guest.snapshot().isSyncLost());
		assertEquals(1, guest.chat.stream().filter(line -> line.contains("cannot resolve its cards yet")).count());

		guest.useCatalog(true);
		sim.advance(6_000L);

		RaceSnapshot recovered = guest.snapshot();
		assertEquals(RaceSnapshot.State.RUNNING, recovered.getState());
		assertFalse(recovered.isSyncLost());
		assertEquals(host.snapshot().getRoundId(), recovered.getRoundId());

