	@Test
	public void countsRoundsThroughAScheduledMatchAndDeclaresAWinner()
	{
		RaceSimulation sim = new RaceSimulation();
		SimClient host = sim.join("Host");
		SimClient guest = sim.join("Guest");
		host.config.totalRounds = 3;

		for (int round = 1; round <= 3; round++)
		{
			host.openPack(RaceSimulation.DEFAULT_PACK);
			assertEquals(round, host.snapshot().getMatch().getRound());
			assertEquals(3, host.snapshot().getMatch().getTotalRounds());
			assertEquals(round, guest.snapshot().getMatch().getRound());
			assertEquals("ROUND " + round + " / 3", guest.snapshot().getMatch().label());

			sim.startTimer(5);
			host.obtain(SHARK, 1);
			guest.obtain(SHARK, 1);
			host.inventory.remove(SHARK);
			guest.inventory.remove(SHARK);
		}

		MatchState finished = host.snapshot().getMatch();
		assertTrue(finished.isComplete());
		assertEquals(3, finished.getRoundsPlayed());
		assertEquals("Host", finished.getLeader());
		assertEquals(15, finished.getLeaderPoints());
		assertTrue(guest.snapshot().getMatch().isComplete());
		assertTrue(host.chat.contains(RaceService.CHAT_PREFIX + "That was round 3 of 3. Host wins with 15 points."));

		// A fourth round is refused until somebody starts a new match.
		host.openPack(RaceSimulation.DEFAULT_PACK);
		assertEquals(RaceSnapshot.State.FINISHED, host.snapshot().getState());
		assertTrue(host.chat.stream().anyMatch(line -> line.contains("This 3-round match is complete")));
	}

