		for (int seat = 2; seat <= 30; seat++)
		{
			field.add(sim.join("Racer " + seat));
		}

		host.openPack(RaceSimulation.DEFAULT_PACK);
		sim.startTimer(5);
		assertEquals(30, host.snapshot().getParticipants().size());

		for (SimClient finisher : field)
		{
			sim.advance(600L);
			finisher.obtain(SHARK, 1);
		}

		RaceSnapshot hosted = host.snapshot();
		assertEquals(30, hosted.getPlacements().size());
		assertEquals(Arrays.asList(5, 4, 3, 2, 1), points(hosted).subList(0, 5));
		for (int place = 5; place < 30; place++)
		{
			assertEquals("Place " + (place + 1) + " scores nothing",
				Integer.valueOf(0), points(hosted).get(place));
		}
		assertEquals(RaceSnapshot.State.FINISHED, hosted.getState());

		// The whole field agrees on the result table.
		for (SimClient racer : field)
		{
			assertEquals(placementNames(hosted), placementNames(racer.snapshot()));
		}
	}

