	{
		RaceSimulation sim = new RaceSimulation();
		SimClient host = sim.join("Host");
		SimClient guest = sim.join("Guest");

		// A completed round banks its points.
		host.openPack(RaceSimulation.DEFAULT_PACK);
		sim.startTimer(5);
		host.obtain(SHARK, 1);
		guest.obtain(SHARK, 1);
		host.inventory.remove(SHARK);
		guest.inventory.remove(SHARK);
		assertEquals(Integer.valueOf(5), host.snapshot().getScores().get("Host"));
		assertEquals(Integer.valueOf(4), host.snapshot().getScores().get("Guest"));

		// The next round is abandoned after somebody already finished it.
		host.openPack(RaceSimulation.DEFAULT_PACK);
		sim.startTimer(5);
		guest.obtain(DRAGON_BONES, 1);
		assertEquals(Integer.valueOf(9), host.snapshot().getScores().get("Guest"));

		host.service.cancelRound();
		sim.drainBus();

		for (SimClient client : Arrays.asList(host, guest))
		{
			RaceSnapshot cancelled = client.snapshot();
			assertEquals(RaceSnapshot.State.IDLE, cancelled.getState());
			assertTrue(cancelled.getPlacements().isEmpty());
			assertTrue(cancelled.getDnfPlayers().isEmpty());
			// Only the cancelled round is reversed; the first round still counts.
			assertEquals(Integer.valueOf(5), cancelled.getScores().get("Host"));
			assertEquals(Integer.valueOf(4), cancelled.getScores().get("Guest"));
		}
		assertTrue(guest.chat.contains(RaceService.CHAT_PREFIX + "The host cancelled the round. No points were awarded."));
	}

