	private static SimClient carrying(RaceSimulation sim, String playerName, int itemId)
	{
		SimClient racer = sim.join(playerName);
		racer.inventory.put(itemId, 1);
		return racer;
	}

	private static RaceCard cardAt(SimClient simClient, int index)
	{
		return simClient.snapshot().getCards().get(index);
	}

	private static List<String> placementNames(RaceSnapshot snapshot)
	{
		List<String> names = new ArrayList<>();
		for (RacePlacement placement : snapshot.getPlacements())
		{
			names.add(placement.getPlayerName());
		}
		return names;
	}

	private static List<Integer> places(RaceSnapshot snapshot)
	{
		List<Integer> values = new ArrayList<>();
		for (RacePlacement placement : snapshot.getPlacements())
		{
			values.add(placement.getPlace());
		}
		return values;
	}

	private static List<Integer> points(RaceSnapshot snapshot)
	{
		List<Integer> values = new ArrayList<>();
		for (RacePlacement placement : snapshot.getPlacements())
		{
			values.add(placement.getPoints());
		}
		return values;
	}

	private static List<Integer> cardIndexes(RaceSnapshot snapshot)
	{
		List<Integer> values = new ArrayList<>();
		for (RacePlacement placement : snapshot.getPlacements())
		{
			values.add(placement.getCardIndex());
		}
		return values;
	}
}

package com.tcgrace;

/**
 * Mutable {@link TcgRaceConfig} for simulated clients.
 *
 * <p>Every setting inherits the real default from the interface unless a test overrides the matching
 * field, so a simulation always starts from the configuration a player would actually ship with.</p>
 */
final class SimConfig implements TcgRaceConfig
{
	Integer countdownSeconds;
	Integer roundTimeoutMinutes;
	Integer dnfGraceMinutes;
	Integer scoringPlaces;
	Boolean allowLocalWithoutParty;
	Boolean lockCountdownActions;
	Boolean requireKandarinMonastery;
	Boolean invalidateWithdrawals;
	Boolean invalidateTrading;
	Boolean autoStartFromPack;
	Boolean validateStarterLoadout;
	Boolean requireEveryStarterItem;
	Boolean invalidateGrandExchange;
	Boolean requireEveryoneReady;
	Integer totalRounds;
	String requiredStarterItems;

	@Override
	public int totalRounds()
	{
		return totalRounds == null ? TcgRaceConfig.super.totalRounds() : totalRounds;
	}

	@Override
	public boolean requireEveryoneReady()
	{
		return requireEveryoneReady == null ? TcgRaceConfig.super.requireEveryoneReady() : requireEveryoneReady;
	}

	@Override
	public boolean invalidateGrandExchange()
	{
		return invalidateGrandExchange == null ? TcgRaceConfig.super.invalidateGrandExchange() : invalidateGrandExchange;
	}

	@Override
	public String requiredStarterItems()
	{
		return requiredStarterItems == null ? TcgRaceConfig.super.requiredStarterItems() : requiredStarterItems;
	}

	@Override
	public boolean validateStarterLoadout()
	{
		return validateStarterLoadout == null ? TcgRaceConfig.super.validateStarterLoadout() : validateStarterLoadout;
	}

	@Override
	public boolean requireEveryStarterItem()
	{
		return requireEveryStarterItem == null ? TcgRaceConfig.super.requireEveryStarterItem() : requireEveryStarterItem;
	}

	@Override
