package com.tcgrace;

import java.io.ByteArrayOutputStream;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.zip.GZIPOutputStream;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class TcgPackDetectorTest
{
	private static final byte[] XOR_SALT = {
		0x52, 0x4c, 0x54, 0x43, 0x47, 0x7c, 0x6f, 0x73,
		0x72, 0x73, 0x2d, 0x74, 0x63, 0x67, 0x21
	};

	@Test
	public void decodesCurrentAndLegacySaveFormats() throws Exception
	{
		String json = "{\"openedPacks\":12}";
		byte[] gzip = gzip(json);
		assertEquals(json, TcgPackDetector.decode("RLTCG_v3:" + Base64.getEncoder().encodeToString(gzip)));

		byte[] legacy = gzip.clone();
		for (int i = 0; i < legacy.length; i++)
		{
			legacy[i] ^= XOR_SALT[i % XOR_SALT.length];
		}
		assertEquals(json, TcgPackDetector.decode("RLTCG_v2:" + Base64.getEncoder().encodeToString(legacy)));
	}

	@Test
	public void detectsFivePullsIncludingDuplicateNames()
	{
		Map<String, TcgPackDetector.StoredCardInstance> before = new LinkedHashMap<>();
		Map<String, TcgPackDetector.StoredCardInstance> after = new LinkedHashMap<>();
		for (int i = 0; i < 5; i++)
		{
			TcgPackDetector.StoredCardInstance instance = card("new-" + i,
				i < 2 ? "Goblin" : "Card " + i, 123456L);
			after.put(instance.id, instance);
		}

		List<List<String>> packs = TcgPackDetector.detectPacks(before, after);

		assertEquals(1, packs.size());
		assertEquals(5, packs.get(0).size());
		assertEquals(2, packs.get(0).stream().filter("Goblin"::equals).count());
	}

	@Test
	public void ignoresIncompleteAtomicWrite()
	{
		Map<String, TcgPackDetector.StoredCardInstance> after = new LinkedHashMap<>();
		after.put("one", card("one", "Goblin", 123456L));
		assertTrue(TcgPackDetector.detectPacks(new LinkedHashMap<>(), after).isEmpty());
	}

	@Test
	public void preservesCurrentVariantId()
	{
		TcgPackDetector.CardVariant variant = new TcgPackDetector.CardVariant();
		variant.id = "card-instance-123";
		variant.pulledAt = 123456L;

		TcgPackDetector.CardEntry entry = new TcgPackDetector.CardEntry();
		entry.cardName = "Goblin";
		entry.variants = Collections.singletonList(variant);

		TcgPackDetector.StoredState state = new TcgPackDetector.StoredState();
		state.cardEntries = Collections.singletonList(entry);

		assertEquals("card-instance-123", state.expandedInstances().get(0).id);
	}

	@Test
	public void recoversMostRecentCompleteSavedPack()
	{
		List<TcgPackDetector.StoredCardInstance> cards = new java.util.ArrayList<>();
		for (int i = 0; i < 5; i++)
		{
			cards.add(card("old-" + i, "Old " + i, 100L));
			cards.add(card("new-" + i, "New " + i, 200L));
		}
		cards.add(card("incomplete", "Later but incomplete", 300L));

		List<String> latest = TcgPackDetector.latestCompletePack(cards);

		assertEquals(5, latest.size());
		assertTrue(latest.stream().allMatch(name -> name.startsWith("New ")));
	}

	@Test
	public void parsesLocalRevealMessages()
	{
		assertEquals("Goblin", TcgPackDetector.parseLocalPullMessage(
			"[OSRS TCG] You just added Goblin to your collection!"));
		assertEquals("Revenant dragon", TcgPackDetector.parseLocalPullMessage(
			"[<col=c4941a>OSRS TCG</col>] You just added duplicate Revenant dragon (foil) to your collection!"));
		assertNull(TcgPackDetector.parseLocalPullMessage(
			"[OSRS TCG] Someone else just added Goblin to their collection!"));
	}

	private static TcgPackDetector.StoredCardInstance card(String id, String name, long pulledAt)
	{
		TcgPackDetector.StoredCardInstance card = new TcgPackDetector.StoredCardInstance();
		card.id = id;
		card.cardName = name;
		card.pulledAt = pulledAt;
		return card;
	}

	private static byte[] gzip(String value) throws Exception
	{
		ByteArrayOutputStream output = new ByteArrayOutputStream();
		try (GZIPOutputStream gzip = new GZIPOutputStream(output))
		{
			gzip.write(value.getBytes(StandardCharsets.UTF_8));
		}
		return output.toByteArray();
	}
}

